                vm.caa_pdf_busy = null;
                if (res.success === false) {
                    ToastService.error('PDF Unavailable', res.message || 'The PDF could not be generated.');
                    return;
                }
                var url = URL.createObjectURL(res.blob);
                var a = document.createElement('a');
                a.href = url;
