    DefaultCourseCopyModalCtrl.$inject = ['$uibModalInstance', 'DefaultCoursesService', 'ToastService', '$timeout', 'course'];
    function DefaultCourseCopyModalCtrl($uibModalInstance, DefaultCoursesService, ToastService, $timeout, course) {
        var vm = this;

        vm.course = course;
        vm.stage = 'pick';       // pick | preview | confirm_force | copying | done | busy
        vm.busy = false;
        vm.q = '';
        vm.results = [];
        vm.searching = false;
        vm.club = null;          // chosen target
        vm.preview = null;
        vm.result = null;        // copy response
        vm.message = '';

        // Human labels for the will_create/result counter keys.
        vm.countLabels = {
            lessons: 'lessons', lesson_items: 'marking items', lesson_bullets: 'briefing bullets',
            lesson_tem: 'TEM entries', lesson_content_files: 'content files', exams: 'ground exams',
            questionnaires: 'questionnaires', questionnaire_questions: 'questionnaire questions',
            questionnaire_links: 'questionnaire links', course_materials: 'course materials',
            solo_requirements: 'pre-solo requirements'
        };
        vm.countKeys = Object.keys(vm.countLabels);

        // Debounced club search (same q=/≤20 pattern as the tpc people picker).
        var debounce = null;
        vm.search = function() {
            if (debounce) { $timeout.cancel(debounce); }
            debounce = $timeout(function() {
                vm.searching = true;
                DefaultCoursesService.Clubs(vm.q).then(function(data) {
                    vm.searching = false;
                    vm.results = (data && data.items) || [];
                });
            }, 300);
        };
        vm.search();   // initial (empty q) list

        vm.pick = function(club) {
            vm.club = club;
            vm.preview = null;
            vm.stage = 'preview';
            vm.busy = true;
            DefaultCoursesService.CopyPreview(vm.course.id, club.id).then(function(data) {
                vm.busy = false;
                if (!data || data.success === false) {
                    vm.stage = 'pick';
                    ToastService.error('Preview Failed', (data && data.message) || 'The copy preview could not be loaded.');
                    return;
                }
                vm.preview = data;
            });
        };
        vm.backToPick = function() { if (!vm.busy) { vm.stage = 'pick'; vm.club = null; vm.preview = null; } };

        vm.doCopy = function(force) {
            vm.stage = 'copying';
            vm.busy = true;
            DefaultCoursesService.Copy(vm.course.id, vm.club.id, !!force).then(function(data) {
                vm.busy = false;
                if (data && data.success !== false) {
                    vm.stage = 'done';
                    vm.result = data;
                    return;
                }
                var err = data && data.error;
                if (err === 'ALREADY_COPIED') {
                    // Confirm, then re-POST with force:true.
                    vm.stage = 'confirm_force';
                    vm.existingCopies = data.existing_copies || (vm.preview && vm.preview.existing_copies) || [];
                } else if (err === 'COPY_BUSY') {
                    // Never auto-retry a held-lock copy.
                    vm.stage = 'busy';
                    vm.message = data.message || 'A copy of this course to this club is already running.';
                } else {
                    vm.stage = 'preview';
                    ToastService.error('Copy Failed', (data && data.message) || 'The course could not be copied.');
                }
            });
        };

        vm.close = function(copied) { $uibModalInstance.close(!!copied); };
        vm.dismiss = function() { $uibModalInstance.dismiss('cancel'); };
    }

 app.controller('DisplayPairingController', DisplayPairingController);

    DisplayPairingController.$inject = ['ScheduleDisplayService', '$scope', '$interval', '$timeout', '$window'];
    function DisplayPairingController(ScheduleDisplayService, $scope, $interval, $timeout, $window) {
        var vm = this;

        // ── State ──
        vm.code = '';
        vm.codeDigits = [];
        vm.sessionUuid = '';
        vm.paired = false;
        vm.expired = false;
        vm.loading = true;
        vm.error = false;
        vm.error_message = '';
        vm.countdown = 600; // 10 minutes
        vm.countdownDisplay = '10:00';
        vm.current_time = '';

        var pollTimer = null;
        var countdownTimer = null;
        var clockTimer = null;

        // ── Initialise ──
        init();

        function init() {
            updateClock();
            clockTimer = $interval(updateClock, 1000);
            requestNewCode();
        }

        // ── Clock ──
        function updateClock() {
            var now = new Date();
            var hours = String(now.getHours()).padStart(2, '0');
            var mins  = String(now.getMinutes()).padStart(2, '0');
            var secs  = String(now.getSeconds()).padStart(2, '0');
            vm.current_time = hours + ':' + mins + ':' + secs;
        }

        // ── Request a new pairing code ──
        function requestNewCode() {
            vm.loading = true;
            vm.expired = false;
            vm.paired = false;
            vm.error = false;

            ScheduleDisplayService.RequestPairingCode()
                .then(function(data) {
                    vm.loading = false;
                    if (data.success) {
                        vm.code = data.code;
                        vm.codeDigits = data.code.split('');
                        vm.sessionUuid = data.session_uuid;

                        // Calculate countdown from expiry
                        var expiresAt = new Date(data.expires_at).getTime();
                        vm.countdown = Math.floor((expiresAt - Date.now()) / 1000);
                        if (vm.countdown < 0) vm.countdown = 600;

                        updateCountdownDisplay();
                        startPolling();
                        startCountdown();
                    } else {
                        vm.error = true;
                        vm.error_message = data.message || 'Failed to generate pairing code. Please refresh the page.';
                    }
                }, function() {
                    vm.loading = false;
                    vm.error = true;
                    vm.error_message = 'Could not connect to the server. Please check your internet connection and refresh.';
                });
        }

        vm.requestNewCode = requestNewCode;

        // ── Poll for pairing status ──
        function startPolling() {
            stopPolling();
            pollTimer = $interval(function() {
                if (!vm.sessionUuid || vm.paired || vm.expired) return;

                ScheduleDisplayService.CheckPairingStatus(vm.sessionUuid)
                    .then(function(data) {
                        if (data.success && data.paired) {
                            vm.paired = true;
                            stopPolling();
                            stopCountdown();

                            // Redirect to the actual display page after a brief pause
                            $timeout(function() {
                                $window.location.href = '/display/' + data.token;
                            }, 2500);
                        }

                        if (!data.success && data.expired) {
                            vm.expired = true;
                            stopPolling();
                            stopCountdown();
                        }
                    }, function() {
                        // Network error — will retry next poll
                    });
            }, 3000);
        }

        function stopPolling() {
            if (pollTimer) {
                $interval.cancel(pollTimer);
                pollTimer = null;
            }
        }

        // ── Countdown timer ──
        function startCountdown() {
            stopCountdown();
            countdownTimer = $interval(function() {
                vm.countdown--;
                updateCountdownDisplay();
                if (vm.countdown <= 0) {
                    vm.expired = true;
                    stopCountdown();
                    stopPolling();
                }
            }, 1000);
        }

        function stopCountdown() {
            if (countdownTimer) {
                $interval.cancel(countdownTimer);
                countdownTimer = null;
            }
        }

        function updateCountdownDisplay() {
            var mins = Math.max(0, Math.floor(vm.countdown / 60));
            var secs = Math.max(0, vm.countdown % 60);
            vm.countdownDisplay = String(mins).padStart(2, '0') + ':' + String(secs).padStart(2, '0');
        }

        // ── Cleanup ──
        $scope.$on('$destroy', function() {
            stopPolling();
            stopCountdown();
            if (clockTimer) { $interval.cancel(clockTimer); }
        });
    }

// ═══════════════════════════════════════════════════════════════════
//  EmailCancelController — public "this wasn't me" / recovery veto page.
//  /email_cancel/:token — the link in the warning email sent to the
//  CURRENT addresses when a recovery case is opened. GET only SHOWS the
//  summary (masked new address + when the case was opened); the request
//  is cancelled by an explicit POST from the button — mail scanners
//  prefetch links, so the GET must never act.
//  MUST work with no session: no $rootScope.globals access here, and the
//  account_email_confirm endpoints are exempted from the auth interceptor.
//  ANY failure renders the one uniform "invalid or expired" panel — never
//  detail (the backend 404s uniformly too).
//  Backend contract: FRONTEND_ACCOUNT_EMAILS_GUIDE.md §2.3 / §7
// ═══════════════════════════════════════════════════════════════════

app.controller('EmailCancelController', EmailCancelController);

EmailCancelController.$inject = ['$stateParams', 'AccountEmailsService'];
function EmailCancelController($stateParams, AccountEmailsService) {
    var vm = this;

    var token = $stateParams.token;

    vm.state = 'loading';       // loading | summary | done | invalid
    vm.new_email_masked = '';
    vm.openedAtLabel = '';

    vm.busy = false;

    vm.cancelRequest = cancelRequest;

    load();

    function load() {
        if (!token) {
            vm.state = 'invalid';
            return;
        }
        AccountEmailsService.CancelGet(token).then(function(data) {
            if (!data || data.success === false) {
                vm.state = 'invalid';
                return;
            }
            vm.new_email_masked = data.new_email_masked || '';
            vm.openedAtLabel = formatOpenedAt(data.opened_at);
            vm.state = 'summary';
        });
    }

    function cancelRequest() {
        if (vm.busy) { return; }
        vm.busy = true;
        AccountEmailsService.CancelPost(token).then(function(data) {
            vm.busy = false;
            if (data && data.success !== false) {
                vm.state = 'done';
                return;
            }
            vm.state = 'invalid';
        });
    }

    // "opened 26 Oct 2026, 14:05" — moment is loaded globally; fall back to
    // the raw string if it can't be parsed so the line is never blank.
    function formatOpenedAt(value) {
        if (!value) { return ''; }
        if (typeof moment === 'function') {
            var m = moment(value);
            if (m.isValid()) { return m.format('D MMM YYYY, HH:mm'); }
        }
        return String(value);
    }
}

// ═══════════════════════════════════════════════════════════════════
//  EmailConfirmController — public "confirm this email address" page.
//  /email_confirm/:token — the link from the verification email. Works for
//  both kinds of token: 'add' (a second address on the user's account) and
//  'recovery' (a staff-opened recovery case moving the sign-in address).
//  GET only SHOWS the summary; the address is confirmed by an explicit
//  POST from the Confirm button — mail scanners prefetch links, so the GET
//  must never act. A recovery POST may come back with sms_required, in
//  which case a 6-digit code step is shown inline.
//  MUST work with no session: no $rootScope.globals access here, and the
//  account_email_confirm endpoints are exempted from the auth interceptor.
//  ANY failure renders the one uniform "invalid or expired" panel — never
//  detail (the backend 404s uniformly too).
//  Backend contract: FRONTEND_ACCOUNT_EMAILS_GUIDE.md §2.3 / §7
// ═══════════════════════════════════════════════════════════════════

app.controller('EmailConfirmController', EmailConfirmController);

EmailConfirmController.$inject = ['$stateParams', '$timeout', 'AccountEmailsService'];
function EmailConfirmController($stateParams, $timeout, AccountEmailsService) {
    var vm = this;

    var token = $stateParams.token;

    vm.state = 'loading';       // loading | summary | sms | done | invalid
    vm.kind = 'add';            // 'add' | 'recovery'
    vm.email_masked = '';
    vm.first_name = '';

    vm.busy = false;

    // SMS sub-step (recovery only)
    vm.code = '';
    vm.codeError = '';
    vm.attemptsRemaining = null;

    vm.confirmAddress = confirmAddress;
    vm.submitCode = submitCode;
    vm.codeLooksValid = codeLooksValid;

    load();

    function load() {
        if (!token) {
            vm.state = 'invalid';
            return;
        }
        AccountEmailsService.ConfirmGet(token).then(function(data) {
            if (!data || data.success === false) {
                vm.state = 'invalid';
                return;
            }
            vm.kind = data.kind === 'recovery' ? 'recovery' : 'add';
            vm.email_masked = data.email_masked || '';
            vm.first_name = data.first_name || '';
            vm.state = 'summary';
        });
    }

    function confirmAddress() {
        if (vm.busy) { return; }
        vm.busy = true;
        AccountEmailsService.ConfirmPost(token).then(function(data) {
            vm.busy = false;
            if (!data || data.success === false) {
                vm.state = 'invalid';
                return;
            }
            if (data.sms_required) {
                vm.code = '';
                vm.codeError = '';
                vm.attemptsRemaining = null;
                vm.state = 'sms';
                focusCode();
                return;
            }
            vm.state = 'done';
        });
    }

    function codeLooksValid() {
        return /^\d{6}$/.test(String(vm.code || '').trim());
    }

    function submitCode() {
        if (vm.busy) { return; }
        var code = String(vm.code || '').replace(/\s+/g, '');
        if (!/^\d{6}$/.test(code)) {
            vm.codeError = 'Enter the 6-digit code from the text message.';
            focusCode();
            return;
        }
        vm.codeError = '';
        vm.busy = true;
        AccountEmailsService.ConfirmSms(token, code).then(function(data) {
            vm.busy = false;
            // The backend answers a wrong code with success:true + sms_verified:false
            // + error:'WRONG_CODE' (the request itself succeeded) — only a verified
            // code is "done".
            if (data && data.success !== false && data.sms_verified !== false && !data.error) {
                vm.state = 'done';
                return;
            }
            if (data && data.error === 'WRONG_CODE') {
                var left = parseInt(data.attempts_remaining, 10);
                vm.attemptsRemaining = isNaN(left) ? null : left;
                if (vm.attemptsRemaining === 0) {
                    // No attempts left — the token is dead; same uniform panel.
                    vm.state = 'invalid';
                    return;
                }
                vm.codeError = "That code isn't right.";
                vm.code = '';
                focusCode();
                return;
            }
            // Anything else (expired, used, unknown) → the uniform panel.
            vm.state = 'invalid';
        });
    }

    function focusCode() {
        $timeout(function() {
            var el = document.getElementById('field-ec-code');
            if (el) { el.focus(); }
        }, 50);
    }
}

app.controller('EmailLogController', EmailLogController);

    EmailLogController.$inject = ['EmailLogService', 'ClubService', '$rootScope', '$scope', '$state', '$uibModal', '$timeout', 'ToastService'];
    function EmailLogController(EmailLogService, ClubService, $rootScope, $scope, $state, $uibModal, $timeout, ToastService) {

        // Email log — one controller for both scopes
        // (FRONTEND_EMAIL_LOG_AND_PREFERENCES_GUIDE.md §3):
        //   platform  (dashboard.super_admin.emails)     ToAviate staff, every club
        //   club      (dashboard.manage_club.email_log)  managers, scoped to their club
        // The backend is authoritative — a non-permitted caller gets success:false.

        var vm = this;

        vm.user = $rootScope.globals.currentUser;
        vm.scope = ($state.current.data && $state.current.data.scope) || 'platform';
        vm.is_platform = vm.scope === 'platform';
        vm.club_id = vm.is_platform ? null : (vm.user.current_club_admin && vm.user.current_club_admin.id);
        vm.club_title = vm.is_platform ? '' : (vm.user.current_club_admin && vm.user.current_club_admin.title);

        vm.allowed = vm.is_platform
            ? $rootScope.isToAviateStaff()
            : !!(vm.club_id && vm.user.access && vm.user.access.manager && vm.user.access.manager.indexOf(vm.club_id) > -1);

        var logScope = vm.is_platform ? null : { club_id: vm.club_id };

        // ── Filters / paging ──
        vm.filters = { q: '', status: '', category: '', source: '', club_id: '', is_cron: '', from: '', to: '' };
        vm.page = 1;
        vm.per_page = 50;
        vm.total = 0;
        vm.pages = 0;
        vm.rows = [];
        vm.loading = true;
        vm.load_failed = false;
        vm.load_failed_message = '';

        vm.sources = [];
        vm.categories = ['reminder', 'notification', 'transactional', 'system'];
        vm.statuses = ['sent', 'suppressed', 'failed', 'logged'];
        vm.clubs = [];

        // ── Stats ──
        vm.stats_days = 30;
        vm.stats = null;
        vm.stats_loading = true;
        vm.by_day = [];        // [{day, sent, suppressed, failed, logged, total}]
        vm.by_day_max = 0;
        vm.by_source = [];     // [{source, sent, suppressed, failed, logged, total}]
        vm.hover_day = null;

        // ── Cron previews (dry runs) ──
        vm.dry_runs = EmailLogService.DRY_RUNS;
        vm.preview = { open: false, loading: false, run: null, result: null, club_id: null };

        vm.load = load;
        vm.applyFilters = applyFilters;
        vm.clearFilters = clearFilters;
        vm.setQuick = setQuick;
        vm.goPage = goPage;
        vm.openDetail = openDetail;
        vm.loadStats = loadStats;
        vm.setStatsDays = setStatsDays;
        vm.runPreview = runPreview;
        vm.closePreview = closePreview;
        vm.statusIcon = statusIcon;
        vm.statusLabel = statusLabel;
        vm.triggeredBy = triggeredBy;
        vm.recipientName = recipientName;
        vm.shortSource = shortSource;
        vm.reasonLabel = reasonLabel;
        vm.decisionClass = decisionClass;
        vm.decisionLabel = decisionLabel;
        vm.barHeight = barHeight;
        vm.dayLabel = dayLabel;
        vm.hasActiveFilters = hasActiveFilters;

        // Declared before activate() runs: a hoisted-but-unassigned counter would
        // make the first response look stale and get dropped.
        var loadSeq = 0;
        var searchTimer = null;

        if (vm.allowed) {
            activate();
        } else {
            vm.loading = false;
            vm.stats_loading = false;
        }

        function activate() {
            EmailLogService.Sources().then(function(data) {
                if (data && data.success) {
                    vm.sources = data.sources || [];
                    if (data.categories && data.categories.length) { vm.categories = data.categories; }
                    if (data.statuses && data.statuses.length) { vm.statuses = data.statuses; }
                }
            });
            if (vm.is_platform) {
                ClubService.GetAll().then(function(data) {
                    if (data && data.success === false) { return; }
                    vm.clubs = (data && data.clubs) || (angular.isArray(data) ? data : []);
                });
            }
            load();
            loadStats();
        }

        // ── List ──

        function load() {
            var seq = ++loadSeq;
            vm.loading = true;
            vm.load_failed = false;
            var params = angular.extend({ page: vm.page, per_page: vm.per_page }, vm.filters);
            if (!vm.is_platform) { delete params.club_id; }
            EmailLogService.List(logScope, params).then(function(data) {
                if (seq !== loadSeq) { return; }   // a newer request superseded this one
                vm.loading = false;
                if (data && data.success) {
                    vm.rows = data.rows || [];
                    vm.total = data.total || 0;
                    vm.pages = data.pages || 0;
                    vm.page = data.page || vm.page;
                } else {
                    vm.rows = [];
                    vm.load_failed = true;
                    vm.load_failed_message = (data && data.message) || 'We could not load the email log.';
                }
            });
        }

        function applyFilters(debounced) {
            vm.page = 1;
            if (debounced) {
                if (searchTimer) { $timeout.cancel(searchTimer); }
                searchTimer = $timeout(load, 350);
            } else {
                load();
            }
        }

        function clearFilters() {
            vm.filters = { q: '', status: '', category: '', source: '', club_id: '', is_cron: '', from: '', to: '' };
            applyFilters(false);
        }

        // Quick chips on the stat tiles: click "Suppressed" → filter the list to it.
        function setQuick(status) {
            vm.filters.status = (vm.filters.status === status) ? '' : status;
            applyFilters(false);
        }

        function goPage(p) {
            if (p < 1 || (vm.pages && p > vm.pages) || p === vm.page) { return; }
            vm.page = p;
            load();
        }

        function hasActiveFilters() {
            var f = vm.filters;
            return !!(f.q || f.status || f.category || f.source || f.club_id || f.is_cron !== '' || f.from || f.to);
        }

        // ── Detail modal ──

        function openDetail(row) {
            $uibModal.open({
                animation: true, size: 'lg', windowClass: 'eml-modal',
                templateUrl: 'views/modals/email_log_detail.html',
                controller: 'EmailLogDetailModalController', controllerAs: 'm',
                resolve: {
                    scope: function() { return logScope; },
                    row: function() { return row; }
                }
            });
        }

        // ── Stats ──

        function loadStats() {
            vm.stats_loading = true;
            EmailLogService.Stats(logScope, vm.stats_days).then(function(data) {
                vm.stats_loading = false;
                if (!(data && data.success)) { vm.stats = null; return; }
                vm.stats = data;
                vm.stats.by_status = data.by_status || {};
                vm.stats.by_category = data.by_category || {};
                vm.by_day = pivot(data.by_day || [], 'day', true);
                vm.by_day_max = 0;
                for (var i = 0; i < vm.by_day.length; i++) {
                    if (vm.by_day[i].total > vm.by_day_max) { vm.by_day_max = vm.by_day[i].total; }
                }
                vm.by_source = pivot(data.by_source || [], 'source', false).sort(function(a, b) { return b.total - a.total; });
            });
        }

        function setStatsDays(days) {
            vm.stats_days = days;
            loadStats();
        }

        // [{key, status, c}] → [{key, sent, suppressed, failed, logged, total}]
        function pivot(rows, keyName, fillDays) {
            var map = {}, order = [];
            for (var i = 0; i < rows.length; i++) {
                var k = rows[i][keyName];
                if (!map[k]) {
                    map[k] = { sent: 0, suppressed: 0, failed: 0, logged: 0, total: 0 };
                    map[k][keyName] = k;
                    order.push(k);
                }
                var c = parseInt(rows[i].c, 10) || 0;
                var s = rows[i].status;
                if (map[k][s] === undefined) { map[k][s] = 0; }
                map[k][s] += c;
                map[k].total += c;
            }
            if (fillDays) {
                // Every day in the window gets a column, even when nothing was sent.
                var days = vm.stats_days;
                var out = [];
                var d = new Date(); d.setHours(0, 0, 0, 0);
                for (var j = days - 1; j >= 0; j--) {
                    var dt = new Date(d.getTime() - j * 86400000);
                    var key = dt.getFullYear() + '-' + ('0' + (dt.getMonth() + 1)).slice(-2) + '-' + ('0' + dt.getDate()).slice(-2);
                    out.push(map[key] || { day: key, sent: 0, suppressed: 0, failed: 0, logged: 0, total: 0 });
                }
                return out;
            }
            var list = [];
            for (var n = 0; n < order.length; n++) { list.push(map[order[n]]); }
            return list;
        }

        function barHeight(day, status) {
            if (!vm.by_day_max) { return 0; }
            return Math.round((day[status] / vm.by_day_max) * 100);
        }

        function dayLabel(day) {
            var m = String(day).match(/^(\d{4})-(\d{2})-(\d{2})$/);
            return m ? (parseInt(m[3], 10) + '/' + parseInt(m[2], 10)) : day;
        }

        // ── Cron previews ──

        function runPreview(run) {
            var club = vm.is_platform ? vm.preview.club_id : vm.club_id;
            if (!club) {
                ToastService.warning('Choose a club', 'Pick a club to preview its reminder run.');
                return;
            }
            vm.preview.open = true;
            vm.preview.loading = true;
            vm.preview.run = run;
            vm.preview.result = null;
            EmailLogService.DryRun(run.endpoint, club).then(function(data) {
                vm.preview.loading = false;
                if (data && data.success) {
                    vm.preview.result = data;
                } else {
                    vm.preview.open = false;
                    ToastService.error('Preview failed', (data && data.message) || 'The dry run could not be started.');
                }
            });
        }

        function closePreview() {
            vm.preview.open = false;
            vm.preview.result = null;
        }

        // ── Presentation ──

        function statusIcon(status) {
            switch (status) {
                case 'sent':       return 'fa-check-circle';
                case 'suppressed': return 'fa-bell-slash';
                case 'failed':     return 'fa-exclamation-circle';
                default:           return 'fa-file-alt';
            }
        }

        function statusLabel(status) {
            return status ? status.charAt(0).toUpperCase() + status.slice(1) : '';
        }

        function triggeredBy(row) {
            if (!row) { return ''; }
            if (row.is_cron == 1) { return 'cron'; }
            if (row.triggered_by_first_name || row.triggered_by_last_name) {
                return ((row.triggered_by_first_name || '') + ' ' + (row.triggered_by_last_name || '')).trim();
            }
            return row.triggered_by_user_id ? 'user #' + row.triggered_by_user_id : '—';
        }

        function recipientName(row) {
            if (!row) { return ''; }
            var n = ((row.recipient_first_name || '') + ' ' + (row.recipient_last_name || '')).trim();
            return n || row.intended_to || '—';
        }

        function shortSource(source) {
            if (!source) { return '—'; }
            var parts = String(source).split('.');
            return parts.length > 1 ? parts.slice(1).join('.') : source;
        }

        // Backend reason codes → words a club manager understands.
        var REASONS = {
            user_muted_all_notifications: 'Member has muted all notifications',
            muted_all_notifications: 'Member has muted all notifications',
            muted_booking_reminders: 'Booking reminders turned off',
            muted_booking_emails: 'Booking notifications turned off',
            muted_assignment_emails: 'Course material emails turned off',
            summary_disabled: 'Daily summary turned off',
            already_sent_today: 'Already sent today',
            no_instructor_membership: 'No instructor membership',
            reminder_type_disabled: 'This reminder type is turned off',
            no_email: 'No email address on file'
        };
        function reasonLabel(code) {
            if (!code) { return ''; }
            return REASONS[code] || String(code).replace(/_/g, ' ');
        }

        function decisionClass(decision) {
            if (decision === 'send') { return 'eml-decision--send'; }
            if (decision === 'already_sent_today' || decision === 'no_instructor_membership') { return 'eml-decision--grey'; }
            return 'eml-decision--muted';
        }

        function decisionLabel(decision) {
            return decision === 'send' ? 'Will send' : reasonLabel(decision);
        }
    }


