        		'invitations.introduction': 1,
        		'invitations.your_details': 2,
        		'invitations.next_of_kin':  3,
        		'invitations.your_club':    4,
        		'invitations.tnc':          4,
        		'invitations.direct_debit': 5,
        		'invitations.verified':     6
