 app.controller('PaymentModeSwitchModalCtrl', PaymentModeSwitchModalCtrl);

    PaymentModeSwitchModalCtrl.$inject = ['$uibModalInstance', 'status', 'club_name', 'PaymentModeService', 'ToastService'];
    function PaymentModeSwitchModalCtrl($uibModalInstance, status, club_name, PaymentModeService, ToastService) {
        var vm = this;

        vm.status = status || {};
        vm.club_name = club_name || 'this club';
        vm.club_id = vm.status.club_id;

        // The mode we are switching TO. Backend supplies target_mode; fall back to the
        // opposite of the current mode if it's missing.
        vm.target_mode = vm.status.target_mode ||
            (vm.status.payment_mode === 'live' ? 'sandbox' : 'live');

        vm.target_label = (vm.target_mode || '').toUpperCase();
        vm.is_live_target = vm.target_mode === 'live';

        // Switching back to a mode we've used before can restore previously-saved details.
        vm.has_archive = !!vm.status.target_mode_has_archive;

        vm.members_with_saved_card = vm.status.members_with_saved_card || 0;
        vm.members_with_direct_debit = vm.status.members_with_direct_debit || 0;

        // Typed-confirmation phrase the user must enter exactly.
        vm.confirm_phrase = 'SWITCH TO ' + vm.target_label;
        vm.confirm_text = '';
        vm.note = '';
        vm.submitting = false;

        // Action button is enabled only when the typed text matches exactly.
        vm.canSubmit = function() {
            return !vm.submitting && vm.confirm_text === vm.confirm_phrase;
        };

        vm.confirm = function() {
            if (!vm.canSubmit()) { return; }

            vm.submitting = true;

            var body = {
                to_mode: vm.target_mode,
                confirm: true,
                note: vm.note || null
            };

            PaymentModeService.Switch(vm.club_id, body).then(function(data) {
                if (data && data.success) {
                    $uibModalInstance.close(data);
                    return;
                }

                // All failure shapes come back as HTTP 200 with success:false.
                vm.submitting = false;

                if (data && data.code === 'forbidden') {
                    ToastService.error('Not Allowed', 'Only ToAviate staff can change a club\'s payment mode.');
                    return;
                }

                var msg = (data && (data.error || (data.message && data.message.error))) ||
                    'The payment mode could not be switched. Please try again.';
                ToastService.error('Switch Failed', msg);
            });
        };

        vm.cancel = function() {
            $uibModalInstance.dismiss('cancel');
        };
    }

// ─────────────────────────────────────────────────────
// PersonalLogbookController — a pilot's personal logbook.
// Screens (by route data.screen):
//   list  → My Logbook (combined verified + tentative, totals, by-source, export)
//   add   → add a manual flight
//   edit  → edit a manual flight (manual entries only)
// Manual entries can NEVER carry ToAviate-club tuition — no instructor/tuition/
// club pickers; only free-text external instructor + dual time.
// ─────────────────────────────────────────────────────
app.controller('PersonalLogbookController', PersonalLogbookController);

    PersonalLogbookController.$inject = ['PersonalLogbookService', 'ToastService', '$rootScope', '$scope', '$state', '$stateParams', '$timeout', '$uibModal', 'LogbookEndorsementsService'];
    function PersonalLogbookController(PersonalLogbookService, ToastService, $rootScope, $scope, $state, $stateParams, $timeout, $uibModal, LogbookEndorsementsService) {
        var vm = this;

        vm.screen = $state.current.data.screen;
        vm.user = $rootScope.globals.currentUser;
        vm.loading = false;
        vm.saving = false;

        vm.capacities = ['P1', 'PICUS', 'P2', 'PUT', 'INSTRUCTOR'];

        vm.back = function() { $state.go('dashboard.my_account.logbook'); };

        switch (vm.screen) {
            case 'list':     initList(); break;
            case 'stats':    initStats(); break;
            case 'import':   initImport(); break;
            case 'skydemon': initSkydemon(); break;
            default:         initForm(); break;   // add / edit
        }

        // ════════════════════════════════════════════
        // LIST — combined logbook
        // ════════════════════════════════════════════
        function initList() {
            vm.filters = { from: null, to: null };

            // ── Display preferences (persisted in localStorage) ──
            //  timeFormat: 'hms' (HH:mm, default) | 'decimal'
            //  placeFormat: 'name' (airfield name, default) | 'icao'
            try { vm.timeFormat = localStorage.getItem('toaviate_lb_timefmt') || 'hms'; } catch (e) { vm.timeFormat = 'hms'; }
            try { vm.placeFormat = localStorage.getItem('toaviate_lb_placefmt') || 'name'; } catch (e) { vm.placeFormat = 'name'; }

            vm.toggleTimeFormat = function() {
                vm.timeFormat = (vm.timeFormat === 'hms') ? 'decimal' : 'hms';
                try { localStorage.setItem('toaviate_lb_timefmt', vm.timeFormat); } catch (e) {}
            };
            vm.togglePlaceFormat = function() {
                vm.placeFormat = (vm.placeFormat === 'name') ? 'icao' : 'name';
                try { localStorage.setItem('toaviate_lb_placefmt', vm.placeFormat); } catch (e) {}
            };

            load();
        }

        // Format a decimal-hours value per the user's chosen display.
        //   hms     → "1:30"   (HH:mm, same converter the rest of the app uses)
        //   decimal → "1.5"    (one-dp decimal hours)
        vm.fmtTime = function(time) {
            var n = parseFloat(time);
            if (!n) return vm.timeFormat === 'decimal' ? '' : '';   // blank for 0/empty in the table
            if (vm.timeFormat === 'decimal') {
                return (Math.round(n * 100) / 100).toString();
            }
            var sign = n < 0 ? '-' : '';
            var hour = Math.floor(Math.abs(n));
            var min = Math.round((Math.abs(n) * 60) % 60);
            if (min === 60) { hour++; min = 0; }
            return sign + hour + ':' + (min < 10 ? '0' : '') + min;
        };
        // Same, but shows "0:00" / "0" rather than blank — for the headline totals.
        vm.fmtTotal = function(time) {
            var n = parseFloat(time) || 0;
            if (vm.timeFormat === 'decimal') return (Math.round(n * 100) / 100).toString();
            var hour = Math.floor(n);
            var min = Math.round((n * 60) % 60);
            if (min === 60) { hour++; min = 0; }
            return hour + ':' + (min < 10 ? '0' : '') + min;
        };

        // Departure/arrival place per the user's chosen display.
        // The API exposes the airfield name (*_airport) and ICAO code
        // (*_airport_code) separately, plus *_place (the code) for back-compat.
        //   name mode (default): show the airfield NAME, ICAO on hover.
        //   icao mode:           show the ICAO code, name on hover.
        // Each mode falls back to whatever is available if a field is missing
        // (e.g. a freeform private strip that only has *_place).
        vm.depPlace = function(e) {
            var code = e.departure_airport_code || e.departure_place || '';
            var name = e.departure_airport || '';
            return (vm.placeFormat === 'icao') ? (code || name) : (name || code);
        };
        vm.arrPlace = function(e) {
            var code = e.arrival_airport_code || e.arrival_place || '';
            var name = e.arrival_airport || '';
            return (vm.placeFormat === 'icao') ? (code || name) : (name || code);
        };
        // The other format, shown in the tooltip on hover.
        vm.depPlaceAlt = function(e) {
            var code = e.departure_airport_code || e.departure_place || '';
            var name = e.departure_airport || '';
            return (vm.placeFormat === 'icao') ? name : code;
        };
        vm.arrPlaceAlt = function(e) {
            var code = e.arrival_airport_code || e.arrival_place || '';
            var name = e.arrival_airport || '';
            return (vm.placeFormat === 'icao') ? name : code;
        };

        function load() {
            vm.loading = true;
            var f = {};
            if (vm.filters.from) f.from = toYMD(vm.filters.from);
            if (vm.filters.to) f.to = toYMD(vm.filters.to);
            PersonalLogbookService.GetLogbook(f).then(function(data) {
                vm.loading = false;
                if (data && data.success === false) {
                    ToastService.error('Could not load logbook', data.message || '');
                    vm.entries = []; vm.totals = null; vm.bySource = [];
                    return;
                }
                vm.entries = data.entries || [];
                vm.totals = data.totals || null;
                vm.bySource = data.by_source || [];
            });
        }
        vm.applyFilter = function() { load(); };
        vm.clearFilter = function() { vm.filters = { from: null, to: null }; load(); };

        vm.editEntry = function(e) {
            if (e.kind !== 'manual') return;   // only manual rows are editable
            $state.go('dashboard.my_account.logbook_edit', { entry_id: e.ref_id });
        };

        // Open the flight replay/debrief when a recorded track exists.
        // Club flights replay via /flight_replay/{pls_id}; SkyDemon manual
        // entries (kind 'manual' + has_track) via the SD track endpoint
        // (src=sd, flight_id = the manual entry id).
        vm.canReplay = function(e) {
            return !!(e && e.has_track && e.ref_id);
        };
        vm.viewReplay = function(e) {
            if (!vm.canReplay(e)) return;
            $state.go('dashboard.flight_replay', {
                flight_id: e.ref_id,
                src: (e.kind === 'manual') ? 'sd' : undefined
            });
        };
        // "SD" chip — entries created from a SkyDemon upload.
        vm.isSkyDemon = function(e) {
            return !!(e && (e.track_source === 'SD' || e.source === 'SkyDemon'));
        };

        vm.deleteEntry = function(e) {
            if (e.kind !== 'manual') return;
            e._confirmDelete = true;
        };
        vm.cancelDelete = function(e) { e._confirmDelete = false; };
        vm.confirmDelete = function(e) {
            e._deleting = true;
            PersonalLogbookService.DeleteManual(e.ref_id).then(function(data) {
                if (data && data.success) {
                    ToastService.success('Deleted', 'Manual entry removed.');
                    load();
                } else {
                    e._deleting = false;
                    ToastService.error('Could not delete', (data && data.message) || '');
                }
            });
        };

        vm.exporting = false;
        vm.exportLogbook = function(format) {
            vm.exporting = true;
            var f = {};
            if (vm.filters.from) f.from = toYMD(vm.filters.from);
            if (vm.filters.to) f.to = toYMD(vm.filters.to);
            PersonalLogbookService.Download(format, f).then(function(res) {
                vm.exporting = false;
                if (res && res.success) {
                    ToastService.success('Export ready', 'Your logbook is downloading.');
                } else {
                    ToastService.error('Export failed', (res && res.message) || '');
                }
            });
        };

        // ════════════════════════════════════════════
        // ENDORSEMENTS — instructor/examiner stamps on a line
        // Drawer state uses the same _underscore transient-flag
        // convention as _wxOpen (stripped from save payloads).
        // ════════════════════════════════════════════

        vm.toggleEndorsements = function(e) {
            e._endOpen = !e._endOpen;
            if (e._endOpen && !e._endRows) { reloadEndorsements(e); }
        };

        function reloadEndorsements(e) {
            e._endLoading = true;
            LogbookEndorsementsService.ForLine(e.kind, e.ref_id).then(function(data) {
                e._endLoading = false;
                if (data && data.success === false) {
                    ToastService.error('Could not load endorsements', data.message || '');
                    e._endRows = e._endRows || [];
                    return;
                }
                e._endRows = data.endorsements || [];
                // Keep the row badge in sync (server rule: signed || confirmed).
                e.endorsed = e._endRows.some(function(r) {
                    return r.status === 'signed' || r.status === 'confirmed';
                }) ? 1 : 0;
                e.endorsements = e._endRows;
            });
        }

        // Status → label/tone. Only signed/confirmed are real stamps; the
        // rest are workflow state and render subtly.
        vm.endStatusLabel = function(r) {
            switch (r.status) {
                case 'pending_instructor':    return 'Awaiting instructor';
                case 'signed':                return 'Signed';
                case 'pending_email_confirm': return r.has_signature_image ? 'Signed — awaiting email confirmation' : 'Awaiting confirmation';
                case 'confirmed':             return 'Confirmed';
                case 'declined':              return 'Declined';
                default:                      return r.status;
            }
        };
        vm.endStatusTone = function(r) {
            if (r.status === 'signed' || r.status === 'confirmed') return 'good';
            if (r.status === 'declined') return 'bad';
            return 'wait';
        };
        vm.endDate = function(r) { return r.confirmed_at || r.signed_at || null; };

        // ── Request an in-app signature (club lines only) ──
        vm.openRequestSignature = function(e) {
            if (e.kind !== 'club') { return; }   // manual lines are external-flow only
            $uibModal.open({
                templateUrl: 'views/modals/endorsement_request_modal.html',
                controller: 'EndorsementRequestModalCtrl',
                controllerAs: 'vm',
                backdrop: 'static',
                windowClass: 'sec-modal-window',
                resolve: { entry: function() { return { ref_id: e.ref_id, club_id: e.club_id, source: e.source,
                                                        flight_date: e.flight_date, registration: e.registration }; } }
            }).result.then(function(saved) {
                if (saved) {
                    ToastService.success('Signature Requested', 'The instructor will see it in their signing queue.');
                    reloadEndorsements(e);
                }
            }, function() {});
        };

        // ── Record an external endorsement (any line) ──
        vm.openAddExternal = function(e) {
            $uibModal.open({
                templateUrl: 'views/modals/endorsement_external_modal.html',
                controller: 'EndorsementExternalModalCtrl',
                controllerAs: 'vm',
                backdrop: 'static',
                size: 'lg',
                windowClass: 'sec-modal-window',
                resolve: { entry: function() { return { kind: e.kind, ref_id: e.ref_id,
                                                        flight_date: e.flight_date, registration: e.registration }; } }
            }).result.then(function(result) {
                if (result && result.saved) {
                    if (result.emailFailed) {
                        ToastService.warning('Saved — Email Not Sent',
                            'The endorsement was recorded but the email could not be sent. Check the address and use Resend.');
                    } else {
                        ToastService.success('Endorsement Recorded',
                            'A confirmation email is on its way to the instructor.');
                    }
                    reloadEndorsements(e);
                }
            }, function() {});
        };

        // ── Resend the confirmation email (backend: max 5 sends, 10-min gap) ──
        vm.resendEndorsement = function(e, r) {
            if (r._resent) { return; }
            r._resending = true;
            LogbookEndorsementsService.Resend(r.id).then(function(data) {
                r._resending = false;
                if (data && data.success !== false) {
                    r._resent = true;      // disable until the drawer reloads
                    ToastService.success('Email Resent', 'The confirmation email was sent again.');
                } else {
                    ToastService.error('Could Not Resend', (data && data.message) || '');
                }
            });
        };

        // ── Audit trail — who did what to a stamp, when, from where ──
        vm.toggleAudit = function(r) {
            r._auditOpen = !r._auditOpen;
            if (r._auditOpen && !r._audit) {
                r._auditLoading = true;
                LogbookEndorsementsService.Audit(r.id).then(function(data) {
                    r._auditLoading = false;
                    if (data && data.success === false) {
                        ToastService.error('Could not load history', data.message || '');
                        r._auditOpen = false;
                        return;
                    }
                    r._audit = (data && data.events) || [];
                });
            }
        };
        vm.auditLabel = function(action) {
            var map = { created: 'Recorded', requested: 'Requested', signed: 'Signed',
                        confirmed: 'Confirmed', declined: 'Declined', revoked: 'Revoked',
                        email_sent: 'Email sent', resent: 'Email resent' };
            return map[action] || (action || '').replace(/_/g, ' ');
        };

        // ── Revoke (inline confirm, same pattern as row delete) ──
        vm.askRevoke = function(r) { r._confirmRevoke = true; };
        vm.cancelRevoke = function(r) { r._confirmRevoke = false; };
        vm.confirmRevoke = function(e, r) {
            r._revoking = true;
            LogbookEndorsementsService.Revoke(r.id).then(function(data) {
                r._revoking = false;
                if (data && data.success !== false) {
                    ToastService.success('Endorsement Removed', 'The endorsement was withdrawn.');
                    reloadEndorsements(e);
                } else {
                    r._confirmRevoke = false;
                    ToastService.error('Could Not Remove', (data && data.message) || '');
                }
            });
        };

        // ════════════════════════════════════════════
        // ADD / EDIT — manual flight form
        // ════════════════════════════════════════════
        function initForm() {
            vm.isEdit = vm.screen === 'edit';
            vm.entry = blankEntry();
            vm.airfields = [];                 // current autocomplete results
            vm.departureAirfield = null;       // picked airfield object {id, code, title}
            vm.arrivalAirfield = null;

            if (vm.isEdit) {
                vm.loading = true;
                PersonalLogbookService.GetManual($stateParams.entry_id).then(function(data) {
                    vm.loading = false;
                    if (data && data.success === false) {
                        ToastService.error('Not found', data.message || 'Could not load that entry.');
                        $state.go('dashboard.my_account.logbook');
                        return;
                    }
                    // Coerce date strings → Date objects for input[type=date].
                    if (data.flight_date) data.flight_date = fromYMD(data.flight_date);
                    // The API may return times as HH:mm:ss; the form (and parseHHMM /
                    // total calc) only understands HH:mm. Trim the seconds so the value
                    // displays correctly and the total can recompute.
                    if (data.departure_time) data.departure_time = toHHMM(data.departure_time);
                    if (data.arrival_time) data.arrival_time = toHHMM(data.arrival_time);
                    vm.entry = angular.extend(blankEntry(), data);
                    // Pre-populate the airfield pickers from the saved entry so the
                    // selection shows on edit (the entry carries id + name + code).
                    if (data.departure_airfield_id || data.departure_airport || data.departure_airport_code) {
                        vm.departureAirfield = {
                            id: data.departure_airfield_id || 0,
                            code: data.departure_airport_code || data.departure_place || '',
                            title: data.departure_airport || data.departure_place || ''
                        };
                    }
                    if (data.arrival_airfield_id || data.arrival_airport || data.arrival_airport_code) {
                        vm.arrivalAirfield = {
                            id: data.arrival_airfield_id || 0,
                            code: data.arrival_airport_code || data.arrival_place || '',
                            title: data.arrival_airport || data.arrival_place || ''
                        };
                    }
                    // If the entry has a total but no usable dep/arr times, show the
                    // manual-total field so the existing value is editable.
                    if ((!vm.entry.departure_time || !vm.entry.arrival_time) && vm.entry.total_time > 0) {
                        vm.manualTotal = true;
                    }
                });
            }
        }

        // Airfield autocomplete — server-side search (shared registry), matching
        // the bookout flow. Triggered by ui-select's refresh as the pilot types.
        var airfieldTimer = null;
        vm.searchAirfields = function(term) {
            if (!term || term.length < 2) return;
            PersonalLogbookService.SearchAirfields(term.replace(/\s/g, '_')).then(function(data) {
                if (data && data.success && angular.isArray(data.airfields)) {
                    vm.airfields = data.airfields;
                } else {
                    vm.airfields = [];
                }
            });
        };

        function blankEntry() {
            return {
                flight_date: null,
                departure_place: '', departure_time: '',
                arrival_place: '', arrival_time: '',
                registration: '',
                aircraft_make: '', aircraft_model: '', aircraft_type: '', aircraft_class: '',
                engine_type: 'single', multi_pilot: 0, is_simulator: 0, sim_type: '',
                capacity: 'P1',
                total_time: null,
                pic_time: null, picus_time: null, copilot_time: null, dual_time: null, instructor_time: null,
                night_time: null, ifr_time: null, cross_country_time: null,
                day_landings: null, night_landings: null,
                instructor_name: '', remarks: '', external_club_name: ''
            };
        }

        // Aircraft registration lookup (debounced, on the registration field).
        var lookupTimer = null;
        vm.lookupAircraft = function() {
            // Registrations are always upper-case — force it as the pilot types
            // (this is the registration field's ng-change handler, add & edit).
            if (vm.entry.registration) {
                vm.entry.registration = vm.entry.registration.toUpperCase();
            }
            var reg = (vm.entry.registration || '').trim();
            if (lookupTimer) $timeout.cancel(lookupTimer);
            if (reg.length < 3) return;
            lookupTimer = $timeout(function() {
                vm.lookingUp = true;
                PersonalLogbookService.LookupAircraft(reg).then(function(data) {
                    vm.lookingUp = false;
                    if (data && data.found) {
                        // Pre-fill, but don't clobber anything the pilot already typed.
                        if (!vm.entry.aircraft_make)  vm.entry.aircraft_make  = data.make && data.make !== '-' ? data.make : vm.entry.aircraft_make;
                        if (!vm.entry.aircraft_model) vm.entry.aircraft_model = data.model && data.model !== '-' ? data.model : vm.entry.aircraft_model;
                        if (!vm.entry.aircraft_type)  vm.entry.aircraft_type  = data.type || vm.entry.aircraft_type;
                        if (!vm.entry.aircraft_class) vm.entry.aircraft_class = data.class || vm.entry.aircraft_class;
                        if (data.engine_type) vm.entry.engine_type = data.engine_type;
                        vm.aircraftFound = true;
                        ToastService.success('Aircraft found', data.registration + ' — ' + (data.type || data.model || ''));
                    } else {
                        vm.aircraftFound = false;
                    }
                });
            }, 500);
        };

        // Which single function-time field a capacity maps to (SEP/MEP are single-
        // pilot, so the whole flight's hours go to one function).
        var CAPACITY_FIELD = {
            'P1': 'pic_time',
            'PICUS': 'picus_time',
            'P2': 'copilot_time',
            'PUT': 'dual_time',
            'INSTRUCTOR': 'instructor_time'
        };
        vm.capacityFieldLabel = function() {
            switch (vm.entry && vm.entry.capacity) {
                case 'P1': return 'PIC';
                case 'PICUS': return 'PICUS';
                case 'P2': return 'P2 / Co-pilot';
                case 'PUT': return 'Dual';
                case 'INSTRUCTOR': return 'Instructor';
                default: return '';
            }
        };

        // Compute the flight total (decimal hours) from departure/arrival HH:MM.
        // Returns 0 if either time is missing/invalid. Handles flights past midnight.
        function parseHHMM(t) {
            if (!t) return null;
            var m = String(t).match(/^(\d{1,2}):(\d{2})$/);
            if (!m) return null;
            var h = +m[1], mi = +m[2];
            if (h > 23 || mi > 59) return null;
            return h * 60 + mi;
        }
        vm.computeTotal = function() {
            var dep = parseHHMM(vm.entry.departure_time);
            var arr = parseHHMM(vm.entry.arrival_time);
            if (dep === null || arr === null) return 0;
            var mins = arr - dep;
            if (mins < 0) mins += 24 * 60;   // crossed midnight
            return Math.round((mins / 60) * 100) / 100;
        };
        // The total used for display + submit: computed from times, unless the
        // pilot has chosen to override it manually (no times, or a known total).
        vm.effectiveTotal = function() {
            if (vm.manualTotal) return parseFloat(vm.entry.total_time) || 0;
            return vm.computeTotal();
        };
        vm.manualTotal = false;
        vm.toggleManualTotal = function() {
            vm.manualTotal = !vm.manualTotal;
            if (!vm.manualTotal) vm.entry.total_time = null;
        };
        // A simulator session has no flight times — switch to manual total entry.
        vm.onSimToggle = function() {
            if (vm.entry.is_simulator) vm.manualTotal = true;
        };

        vm.save = function() {
            var e = vm.entry;

            // Registrations are stored upper-case (covers an edit where the field was
            // never re-touched, so ng-change didn't fire).
            if (e.registration) e.registration = e.registration.toUpperCase();

            // ── Client-side validation (mirror backend rules to avoid round-trips) ──
            if (!e.flight_date) { ToastService.warning('Date required', 'When was the flight?'); return; }

            // Total is computed from the dep/arr times (or a manual override).
            var total = vm.effectiveTotal();
            if (!e.is_simulator && total <= 0) {
                if (vm.manualTotal) {
                    ToastService.warning('Total time required', 'Enter the total flight time (decimal hours).');
                } else {
                    ToastService.warning('Times required', 'Enter departure and arrival times so the total can be calculated (or switch to enter a total manually).');
                }
                return;
            }

            // Capacity drives the single function-time field for the whole flight.
            // Clear all function fields, then set the one for the chosen capacity.
            e.pic_time = e.picus_time = e.copilot_time = e.dual_time = e.instructor_time = null;
            var capField = CAPACITY_FIELD[e.capacity];
            if (capField) e[capField] = total;

            // Condition times (night/IFR/XC) are independent of capacity — just ≤ total.
            var condFields = [
                ['night_time', 'Night time'], ['ifr_time', 'IFR time'], ['cross_country_time', 'Cross-country time']
            ];
            for (var i = 0; i < condFields.length; i++) {
                var v = parseFloat(e[condFields[i][0]]) || 0;
                if (v > total) {
                    ToastService.warning('Time exceeds total', condFields[i][1] + ' cannot exceed the total time.'); return;
                }
            }

            // Build the payload — strip empty values and NEVER send tuition/club fields.
            var payload = {};
            angular.forEach(e, function(val, key) {
                if (key.charAt(0) === '_') return;
                if (val === null || val === '' || val === undefined) return;
                payload[key] = val;
            });
            payload.flight_date = toYMD(e.flight_date);
            payload.total_time = total;
            payload.multi_pilot = e.multi_pilot ? 1 : 0;
            payload.is_simulator = e.is_simulator ? 1 : 0;

            // ── Airfields ──
            // Send the registry id when an airfield was picked (authoritative);
            // also send the code as freeform *_place for back-compat / unlisted strips.
            // A real airfield has id > 0; the "NOT LISTED" sentinel (id 0) is treated
            // as freeform text only.
            delete payload.departure_place; delete payload.arrival_place;
            if (vm.departureAirfield) {
                if (vm.departureAirfield.id > 0) payload.departure_airfield_id = vm.departureAirfield.id;
                if (vm.departureAirfield.code) payload.departure_place = vm.departureAirfield.code;
            }
            if (vm.arrivalAirfield) {
                if (vm.arrivalAirfield.id > 0) payload.arrival_airfield_id = vm.arrivalAirfield.id;
                if (vm.arrivalAirfield.code) payload.arrival_place = vm.arrivalAirfield.code;
            }

            vm.saving = true;
            var call = vm.isEdit
                ? PersonalLogbookService.UpdateManual($stateParams.entry_id, payload)
                : PersonalLogbookService.AddManual(payload);
            call.then(function(data) {
                vm.saving = false;
                if (data && data.success) {
                    ToastService.success(vm.isEdit ? 'Flight updated' : 'Flight logged', 'Added to your tentative hours.');
                    $state.go('dashboard.my_account.logbook');
                } else {
                    ToastService.error('Could not save', (data && data.message) || 'Please check the fields and try again.');
                }
            });
        };

        // ════════════════════════════════════════════
        // STATISTICS
        // ════════════════════════════════════════════
        function initStats() {
            vm.loading = true;
            vm.periodKeys = [
                { key: 'last_1_month',   label: '1 Month' },
                { key: 'last_6_months',  label: '6 Months' },
                { key: 'last_12_months', label: '12 Months' },
                { key: 'last_24_months', label: '24 Months' },
                { key: 'all_time',       label: 'All Time' }
            ];
            vm.activePeriod = 'all_time';
            vm.setPeriod = function(k) { vm.activePeriod = k; };
            vm.period = function() { return (vm.stats && vm.stats.periods) ? vm.stats.periods[vm.activePeriod] : null; };

            PersonalLogbookService.GetStats().then(function(data) {
                vm.loading = false;
                if (data && data.success === false) {
                    ToastService.error('Could not load stats', data.message || '');
                    return;
                }
                vm.stats = data;
                vm.sep = data.sep_currency || { has_sep: false };
            });
            // Reuse the list formatter (defaults to HH:mm; honours the saved pref).
            try { vm.timeFormat = localStorage.getItem('toaviate_lb_timefmt') || 'hms'; } catch (e) { vm.timeFormat = 'hms'; }
        }

        // Percentage helper for the split bars (guards divide-by-zero).
        vm.pct = function(part, whole) {
            part = parseFloat(part) || 0; whole = parseFloat(whole) || 0;
            if (whole <= 0) return 0;
            return Math.round((part / whole) * 100);
        };

        // ════════════════════════════════════════════
        // CSV IMPORT (preview → review → confirm)
        // ════════════════════════════════════════════
        function initImport() {
            vm.importStep = 'pick';        // 'pick' | 'review' | 'done'
            vm.importFileName = '';
            vm.importRows = [];
            vm.importSummary = null;
            vm.importResult = null;
            vm.importing = false;
        }

        // Called from the file input's onchange (same pattern as bs_sync):
        //   onchange="angular.element(this).scope().vm.onImportFile(this.files)"
        // The native event fires outside Angular, so wrap in $apply.
        vm.onImportFile = function(files) {
            $scope.$apply(function() {
                var file = files && files[0];
                if (!file) return;
                // Reject non-CSV early (the backend also rejects, but fail fast).
                if (!/\.csv$/i.test(file.name)) {
                    ToastService.error('CSV only', 'Please export your logbook as CSV and upload that.');
                    return;
                }
                vm.importFileName = file.name;
                vm.importing = true;
                PersonalLogbookService.ImportPreview(file).then(function(data) {
                    vm.importing = false;
                    if (!data || data.success === false) {
                        ToastService.error('Import failed', (data && data.message) || 'Could not read that file.');
                        return;
                    }
                    vm.importSummary = data.summary || null;
                    // Keep each row; pre-select everything that isn't an error.
                    vm.importRows = (data.rows || []).map(function(r) {
                        r._include = (r.status !== 'error');
                        return r;
                    });
                    vm.importStep = 'review';
                });
            });
        };

        vm.importStatusClass = function(status) {
            if (status === 'ready') return 'lb-import-row--ready';
            if (status === 'review') return 'lb-import-row--review';
            return 'lb-import-row--error';
        };
        vm.importIncludedCount = function() {
            return vm.importRows.filter(function(r) { return r._include && r.status !== 'error'; }).length;
        };

        vm.confirmImport = function() {
            var rows = vm.importRows
                .filter(function(r) { return r._include && r.status !== 'error'; })
                .map(function(r) { return r.entry; });
            if (!rows.length) {
                ToastService.warning('Nothing to import', 'Select at least one row.');
                return;
            }
            vm.importing = true;
            PersonalLogbookService.ImportConfirm(rows).then(function(data) {
                vm.importing = false;
                if (!data || data.success === false) {
                    ToastService.error('Import failed', (data && data.message) || '');
                    return;
                }
                vm.importResult = data;   // { imported, failed, results }
                vm.importStep = 'done';
                ToastService.success('Imported', (data.imported || 0) + ' flight(s) added to your logbook.');
            });
        };

        vm.restartImport = function() { initImport(); };

        // ════════════════════════════════════════════
        // SKYDEMON IMPORT (upload → review cards → confirm)
        // Mirrors the CSV flow but multi-file, with staged GPS tracks kept
        // for replay. See FRONTEND_LOGBOOK_SKYDEMON_GUIDE.md.
        // ════════════════════════════════════════════
        var SD_MAX_FILES = 20;
        var SD_MAX_BYTES = 20 * 1024 * 1024;

        function initSkydemon() {
            vm.sdStep = 'pick';            // 'pick' | 'review' | 'done'
            vm.sdCards = [];               // one per uploaded file (in upload order)
            vm.sdSummary = null;
            vm.sdResult = null;
            vm.sdUploading = false;
            vm.sdConfirming = false;
            vm.sdDragOver = false;
        }

        vm.onSdDragState = function(isDragging) {
            vm.sdDragOver = isDragging;
        };

        // Files from lcf-dropzone / lcf-file-select (already inside a digest).
        vm.onSdFiles = function(files) {
            if (!files || !files.length) return;
            if (files.length > SD_MAX_FILES) {
                ToastService.warning('Too many files', 'Please upload at most ' + SD_MAX_FILES + ' log files at a time.');
                return;
            }
            var list = [];
            for (var i = 0; i < files.length; i++) {
                if (files[i].size > SD_MAX_BYTES) {
                    ToastService.error('File too large', files[i].name + ' is over 20 MB.');
                    return;
                }
                list.push(files[i]);
            }

            vm.sdUploading = true;
            PersonalLogbookService.SkydemonPreview(list).then(function(data) {
                vm.sdUploading = false;
                if (!data || data.success === false) {
                    ToastService.error('Upload failed', (data && data.message) || 'Could not read those files.');
                    return;
                }
                vm.sdSummary = data.summary || null;
                vm.sdCards = (data.files || []).map(buildSdCard);
                vm.sdStep = 'review';
            });
        };

        function buildSdCard(f) {
            if (!f.success) {
                return { success: false, file_name: f.file_name, message: f.message, _include: false };
            }
            var card = f;
            card._include = true;
            card._error = null;
            // input[type=date] needs a Date; times edit as HH:MM (seconds trimmed —
            // the confirm validates like a manual entry, which accepts HH:MM).
            card.entry.flight_date = fromYMD(card.entry.flight_date);
            card.entry.departure_time = toHHMM(card.entry.departure_time);
            card.entry.arrival_time = toHHMM(card.entry.arrival_time);
            // Pre-select the airfield candidates matching the resolved ids.
            card._dep = pickSdCandidate(card.departure_candidates, card.entry.departure_airfield_id);
            card._arr = pickSdCandidate(card.arrival_candidates, card.entry.arrival_airfield_id);
            return card;
        }

        function pickSdCandidate(candidates, id) {
            if (!candidates || !candidates.length) return null;
            if (id) {
                for (var i = 0; i < candidates.length; i++) {
                    if (candidates[i].id == id) return candidates[i];
                }
            }
            return candidates[0];
        }

        vm.sdIncludedCount = function() {
            return vm.sdCards.filter(function(c) { return c.success && c._include; }).length;
        };
        vm.sdHasDuplicate = function(c) {
            return !!(c.duplicate && (c.duplicate.manual_entry_id || c.duplicate.club_flight_id));
        };

        vm.confirmSd = function() {
            var rows = [];
            vm.sdCards.forEach(function(c) {
                if (!c.success || !c._include) return;
                rows.push({ upload_token: c.upload_token, entry: buildSdEntry(c) });
            });
            if (!rows.length) {
                ToastService.warning('Nothing selected', 'Tick at least one flight to add.');
                return;
            }
            vm.sdConfirming = true;
            PersonalLogbookService.SkydemonConfirm(rows).then(function(data) {
                vm.sdConfirming = false;
                if (!data || data.success === false) {
                    ToastService.error('Import failed', (data && data.message) || '');
                    return;
                }
                // Annotate cards from the per-row results, keyed by upload_token.
                var byToken = {};
                (data.results || []).forEach(function(r) { byToken[r.upload_token] = r; });
                var stillFailing = [];
                vm.sdCards.forEach(function(c) {
                    var r = c.upload_token ? byToken[c.upload_token] : null;
                    if (!r) return;
                    if (r.success) { c._imported = true; c._include = false; c._error = null; }
                    else { c._error = r.message || 'Could not save this entry.'; stillFailing.push(c); }
                });
                if (data.failed > 0) {
                    // Keep the failed cards on screen for fixing; drop the imported ones.
                    vm.sdCards = vm.sdCards.filter(function(c) { return !c._imported; });
                    ToastService.warning((data.imported || 0) + ' added, ' + data.failed + ' failed',
                        'Fix the highlighted flights and confirm again.');
                } else {
                    vm.sdResult = data;
                    vm.sdStep = 'done';
                    ToastService.success('Flights added', (data.imported || 0) + ' flight(s) with GPS tracks are now in your logbook.');
                }
            });
        };

        // Assemble the entry payload from a card (validated server-side like a
        // manual entry). Capacity drives the single function-time field.
        function buildSdEntry(c) {
            var e = c.entry;
            var total = parseFloat(e.total_time) || 0;
            var entry = {
                flight_date: toYMD(e.flight_date),
                departure_time: e.departure_time || null,
                arrival_time: e.arrival_time || null,
                registration: (e.registration || '').toUpperCase(),
                aircraft_make: e.aircraft_make || '',
                aircraft_model: e.aircraft_model || '',
                aircraft_type: e.aircraft_type || '',
                aircraft_class: e.aircraft_class || '',
                engine_type: e.engine_type || 'single',
                capacity: e.capacity || 'P1',
                total_time: total,
                day_landings: parseInt(e.day_landings, 10) || 0,
                night_landings: parseInt(e.night_landings, 10) || 0,
                remarks: e.remarks || ''
            };
            var capField = CAPACITY_FIELD[entry.capacity];
            if (capField) entry[capField] = total;
            // Night is only sent when the pilot typed one — the backend stores the
            // estimate separately (computed_night_time) and uses it automatically.
            if (e.night_time !== null && e.night_time !== '' && e.night_time !== undefined) {
                entry.night_time = parseFloat(e.night_time) || 0;
            }
            if (c._dep) { entry.departure_airfield_id = c._dep.id; entry.departure_place = c._dep.code; }
            else if (e.departure_place) { entry.departure_place = e.departure_place; }
            if (c._arr) { entry.arrival_airfield_id = c._arr.id; entry.arrival_place = c._arr.code; }
            else if (e.arrival_place) { entry.arrival_place = e.arrival_place; }
            return entry;
        }

        vm.restartSd = function() { initSkydemon(); };

        // Normalise a time value to HH:mm (drop any seconds the API tacks on).
        // "14:30:00" → "14:30"; "9:5" → "09:05"; leaves anything unparseable as-is.
        function toHHMM(t) {
            if (!t) return t;
            var m = String(t).match(/^(\d{1,2}):(\d{2})/);
            if (!m) return t;
            return ('0' + m[1]).slice(-2) + ':' + m[2];
        }

        // ── Date helpers (input[type=date] uses Date objects; API uses YYYY-MM-DD) ──
        function toYMD(d) {
            if (!d) return '';
            if (typeof d === 'string') return d.slice(0, 10);
            var y = d.getFullYear(), m = ('0' + (d.getMonth() + 1)).slice(-2), dd = ('0' + d.getDate()).slice(-2);
            return y + '-' + m + '-' + dd;
        }
        function fromYMD(str) {
            if (!str) return null;
            if (str instanceof Date) return str;
            var p = String(str).slice(0, 10).split('-');
            return p.length === 3 ? new Date(+p[0], +p[1] - 1, +p[2]) : null;
        }
    }

// One controller serves both screens of the ToAviate-admin Platform Earnings
// section (split out of the GoCardless Monitor — health and money are
// separate concerns); the screen is chosen by the route's data.screen.
// Screens: earnings (Stripe + GoCardless fee drill-down, see
// FRONTEND_PLATFORM_FEES_GUIDE.md), revenue (monthly platform fees + tracker
// invoices, see FRONTEND_GCL_MONITOR_GUIDE.md §4). Read-only feature.
//
// Access: ToAviate staff only — the backend is authoritative, this mirrors
// TrackerAdminController's client-side bounce.
app.controller('PlatformEarningsController', PlatformEarningsController);
    PlatformEarningsController.$inject = ['GclMonitorService', 'ClubService', 'ToastService', '$rootScope', '$state', '$location'];
    function PlatformEarningsController(GclMonitorService, ClubService, ToastService, $rootScope, $state, $location) {
        var vm = this;
        vm.user = $rootScope.globals.currentUser;
        vm.is_toaviate_staff = !!(vm.user && vm.user.email && /@toaviate\.com$/i.test(vm.user.email));
        if (!vm.is_toaviate_staff) {
            $location.path('/dashboard');
            return;
        }

        vm.screen = $state.current.data.screen;
        vm.enums  = GclMonitorService.enums;
        vm.loading = false;

        // ── Sub-nav (shared partial views/manageclub/platform_earnings/_nav.html) ──
        vm.nav = [
            { screen: 'earnings', state: 'dashboard.super_admin.platform_earnings',         label: 'Earnings', icon: 'fa-coins' },
            { screen: 'revenue',  state: 'dashboard.super_admin.platform_earnings_revenue', label: 'Revenue',  icon: 'fa-chart-bar' }
        ];
        vm.go = function(state, params) { $state.go(state, params || {}); };

        // ── Shared helpers ────────────────────────────────────────────────
        vm.pretty = function(str) { return str ? String(str).replace(/_/g, ' ') : ''; };
        vm.cur = function(code) {
            if (code === 'GBP' || !code) { return '£'; }
            if (code === 'EUR') { return '€'; }
            if (code === 'USD') { return '$'; }
            return code + ' ';
        };
        vm.num = function(v) { return parseFloat(v) || 0; };

        function toastFail(title, data) {
            ToastService.error(title, (data && data.message) || 'Something went wrong. Please try again.');
        }
        // input[type=date] on Angular 1.4 needs Date objects, not strings
        function ymd(d) { return d ? moment(d).format('YYYY-MM-DD') : null; }

        init();
        function init() {
            switch (vm.screen) {
                case 'earnings': initEarnings(); break;
                case 'revenue':  initRevenue(); break;
            }
        }

        // ══════════════════════════════════════════════════════════════════
        // EARNINGS — Stripe + GoCardless fee drill-down (platform fees guide)
        // ══════════════════════════════════════════════════════════════════
        // Segment order inside a stacked bar, bottom → top. Sandbox/unknown
        // series only appear when the mode toggle is "All".
        var EARN_SERIES = [
            { key: 'live-gocardless',    cls: 'gc',           label: 'GoCardless' },
            { key: 'live-stripe',        cls: 'stripe',       label: 'Stripe' },
            { key: 'sandbox-gocardless', cls: 'gc-test',      label: 'GoCardless (test)' },
            { key: 'sandbox-stripe',     cls: 'stripe-test',  label: 'Stripe (test)' },
            { key: 'unknown-gocardless', cls: 'unknown',      label: 'GoCardless (unknown mode)' },
            { key: 'unknown-stripe',     cls: 'unknown',      label: 'Stripe (unknown mode)' }
        ];
        function initEarnings() {
            // Defaults per the guide: last 12 months, monthly, LIVE money only
            vm.f = {
                from: moment().subtract(11, 'months').startOf('month').toDate(),
                to: new Date(),
                granularity: 'month',
                mode: 'live',
                gateway: 'all',
                club_id: null
            };
            vm.preset = '12m';
            vm.clubs = [];
            ClubService.GetAll().then(function(data) {
                if (data && data.success === false) { return; }
                vm.clubs = (data && data.clubs) || [];
            });
            loadFees();
        }
        vm.presets = [
            { key: 'today', label: 'Today' },
            { key: 'week',  label: 'This week' },
            { key: 'month', label: 'This month' },
            { key: 'year',  label: 'This year' },
            { key: '12m',   label: 'Last 12 months' }
        ];
        vm.applyPreset = function(key) {
            vm.preset = key;
            switch (key) {
                case 'today':
                    vm.f.from = new Date(); vm.f.to = new Date(); vm.f.granularity = 'day'; break;
                case 'week':
                    vm.f.from = moment().startOf('isoWeek').toDate(); vm.f.to = new Date(); vm.f.granularity = 'day'; break;
                case 'month':
                    vm.f.from = moment().startOf('month').toDate(); vm.f.to = new Date(); vm.f.granularity = 'day'; break;
                case 'year':
                    vm.f.from = moment().startOf('year').toDate(); vm.f.to = new Date(); vm.f.granularity = 'month'; break;
                case '12m':
                    vm.f.from = moment().subtract(11, 'months').startOf('month').toDate(); vm.f.to = new Date(); vm.f.granularity = 'month'; break;
            }
            loadFees();
        };
        vm.setGranularity = function(g) { vm.f.granularity = g; vm.preset = 'custom'; loadFees(); };
        vm.setMode = function(m) { vm.f.mode = m; loadFees(); };
        vm.setGateway = function(g) { vm.f.gateway = g; loadFees(); };
        vm.customRangeChanged = function() { vm.preset = 'custom'; loadFees(); };
        vm.clubChanged = function() { loadFees(); };
        vm.clearClub = function() { vm.f.club_id = null; loadFees(); };
        vm.clubTitle = function() {
            for (var i = 0; i < (vm.clubs || []).length; i++) {
                if (vm.clubs[i].id == vm.f.club_id) { return vm.clubs[i].title; }
            }
            return vm.drilled_club_title || ('Club #' + vm.f.club_id);
        };
        function loadFees() {
            vm.loading = true;
            GclMonitorService.Fees({
                from: ymd(vm.f.from),
                to: ymd(vm.f.to),
                granularity: vm.f.granularity,
                club_id: vm.f.club_id,
                mode: vm.f.mode === 'all' ? null : vm.f.mode,
                gateway: vm.f.gateway === 'all' ? null : vm.f.gateway
            }).then(function(data) {
                vm.loading = false;
                if (data && data.success === false) { toastFail('Could not load the earnings report', data); return; }
                vm.earnings = data;
                // Bind the controls to the RESOLVED filters the API echoes back
                var flt = data.filters || {};
                if (flt.granularity) { vm.f.granularity = flt.granularity; }
                if (flt.mode) { vm.f.mode = flt.mode; }
                if (flt.gateway) { vm.f.gateway = flt.gateway; }
                if (flt.from) { vm.f.from = moment(flt.from, 'YYYY-MM-DD').toDate(); }
                if (flt.to) { vm.f.to = moment(flt.to, 'YYYY-MM-DD').toDate(); }
                buildEarnings();
            });
        }
        // Headline money never mixes test traffic: with the toggle on "All"
        // the tiles show LIVE money and test/unknown appear as sub-lines.
        function tileMode() { return vm.f.mode === 'sandbox' ? 'sandbox' : 'live'; }
        function buildEarnings() {
            var rows = (vm.earnings && vm.earnings.summary) || [];
            var currencies = {};
            rows.forEach(function(r) { currencies[r.currency] = true; });
            vm.earn_currencies = Object.keys(currencies);
            vm.earn_tiles = vm.earn_currencies.map(function(c) {
                var t = { currency: c, fees: 0, gross: 0, refunded: 0, gateway_fees: 0, payments: 0,
                          pending: 0, lost: 0, test_fees: 0, unknown_fees: 0 };
                rows.forEach(function(r) {
                    if (r.currency !== c) { return; }
                    if (r.mode === tileMode()) {
                        if (r.fee_state === 'collected') {
                            t.fees += vm.num(r.platform_fees);
                            t.gross += vm.num(r.gross);
                            t.refunded += vm.num(r.refunded);
                            t.gateway_fees += vm.num(r.gateway_fees);
                            t.payments += (parseInt(r.payments, 10) || 0);
                        } else if (r.fee_state === 'pending') {
                            t.pending += vm.num(r.platform_fees);
                        } else {
                            t.lost += vm.num(r.platform_fees);
                        }
                    } else if (r.fee_state === 'collected' && r.mode === 'sandbox') {
                        t.test_fees += vm.num(r.platform_fees);
                    } else if (r.fee_state === 'collected' && r.mode === 'unknown') {
                        t.unknown_fees += vm.num(r.platform_fees);
                    }
                });
                return t;
            }).sort(function(a, b) { return b.fees - a.fees; });
            vm.earn_currency = vm.earn_tiles.length ? vm.earn_tiles[0].currency : null;
            buildModeHidden();
            buildEarnChart();
        }
        // "Empty because of the mode toggle" — mode_counts ignores the mode
        // filter, so when the current mode has nothing but other modes do,
        // explain it instead of rendering a wall of zeros (the normal state
        // on local/dev, where all traffic is sandbox).
        function buildModeHidden() {
            vm.mode_hidden = null;
            if (vm.earn_tiles.length || vm.f.mode === 'all') { return; }
            var others = ((vm.earnings && vm.earnings.mode_counts) || []).filter(function(r) {
                return r.mode !== vm.f.mode && (parseInt(r.payments, 10) || 0) > 0;
            });
            if (!others.length) { return; }
            var byMode = {};
            others.forEach(function(r) {
                byMode[r.mode] = (byMode[r.mode] || 0) + (parseInt(r.payments, 10) || 0);
            });
            var modeNames = { sandbox: 'sandbox', live: 'live', unknown: 'unknown-mode' };
            var parts = Object.keys(byMode).map(function(m) {
                return byMode[m] + ' ' + modeNames[m] + ' payment' + (byMode[m] === 1 ? '' : 's');
            });
            var filterName = vm.f.mode === 'live' ? 'Live' : 'Test';
            var target, targetLabel;
            if (vm.f.mode === 'live') {
                target = byMode.sandbox ? 'sandbox' : 'all';
                targetLabel = byMode.sandbox ? 'Show test mode' : 'Show all modes';
            } else {
                target = byMode.live ? 'live' : 'all';
                targetLabel = byMode.live ? 'Show live money' : 'Show all modes';
            }
            vm.mode_hidden = {
                message: 'No ' + vm.f.mode.replace('sandbox', 'test') + ' payments in this range — ' +
                         parts.join(' and ') + ' are hidden by the ' + filterName + ' filter.',
                target: target,
                targetLabel: targetLabel
            };
        }
        vm.showHiddenMode = function() {
            if (vm.mode_hidden) { vm.setMode(vm.mode_hidden.target); }
        };
        vm.setEarnCurrency = function(c) { vm.earn_currency = c; buildEarnChart(); };
        function buildEarnChart() {
            vm.earn_chart = [];
            vm.earn_legend = [];
            if (!vm.earn_currency || !vm.earnings) { return; }
            var periods = {};
            var present = {};
            ((vm.earnings.by_period) || []).forEach(function(r) {
                if (r.currency !== vm.earn_currency || r.fee_state !== 'collected') { return; }
                var key = r.mode + '-' + r.gateway;
                periods[r.period] = periods[r.period] || {};
                periods[r.period][key] = (periods[r.period][key] || 0) + vm.num(r.platform_fees);
                present[key] = true;
            });
            var keys = Object.keys(periods).sort();
            var max = 0;
            keys.forEach(function(p) {
                var total = 0;
                EARN_SERIES.forEach(function(s) { total += (periods[p][s.key] || 0); });
                periods[p].__total = total;
                max = Math.max(max, total);
            });
            vm.earn_chart = keys.map(function(p, i) {
                var segs = [];
                // DOM renders top-first, so walk the series bottom-up in reverse
                for (var s = EARN_SERIES.length - 1; s >= 0; s--) {
                    var val = periods[p][EARN_SERIES[s].key] || 0;
                    if (!val) { continue; }
                    segs.push({
                        cls: EARN_SERIES[s].cls,
                        label: EARN_SERIES[s].label,
                        val: val,
                        pct: max ? (val / max * 100) : 0
                    });
                }
                return {
                    period: p,
                    label: periodLabel(p),
                    total: periods[p].__total,
                    segs: segs,
                    delay: i * 35,
                    tip: segs.slice().reverse().map(function(sg) {
                        return sg.label + ' ' + vm.cur(vm.earn_currency) + sg.val.toFixed(2);
                    }).join(' · ')
                };
            });
            vm.earn_legend = EARN_SERIES.filter(function(s) { return present[s.key]; });
            // Dedupe the two unknown-gateway rows into one legend swatch
            vm.earn_legend = vm.earn_legend.filter(function(s, i) {
                return vm.earn_legend.map(function(x) { return x.cls; }).indexOf(s.cls) === i;
            });
        }
        function periodLabel(p) {
            switch (vm.f.granularity) {
                case 'day':   return moment(p, 'YYYY-MM-DD').format('D MMM');
                case 'week':  return p.replace(/^\d{4}-/, '') + ' ’' + p.slice(2, 4);
                case 'year':  return p;
                default:      return moment(p, 'YYYY-MM').format('MMM YY');
            }
        }
        // Click a bar → zoom the range to that period, one granularity finer
        vm.drillPeriod = function(c) {
            var finer = { year: 'month', month: 'week', week: 'day' }[vm.f.granularity];
            if (!finer) { return; }
            var m;
            var unit = vm.f.granularity === 'week' ? 'isoWeek' : vm.f.granularity;
            if (vm.f.granularity === 'year') { m = moment(c.period, 'YYYY'); }
            else if (vm.f.granularity === 'month') { m = moment(c.period, 'YYYY-MM'); }
            else { m = moment(c.period, 'GGGG-[W]WW'); }
            if (!m.isValid()) { return; }
            vm.f.from = moment(m).startOf(unit).toDate();
            vm.f.to = moment(m).endOf(unit).toDate();
            vm.f.granularity = finer;
            vm.preset = 'custom';
            loadFees();
        };
        vm.earnClubs = function() {
            var rows = (vm.earnings && vm.earnings.by_club) || [];
            return rows.filter(function(r) { return r.currency === vm.earn_currency; });
        };
        vm.drillClub = function(r) {
            vm.f.club_id = r.club_id;
            vm.drilled_club_title = r.club_title;
            loadFees();
        };
        vm.modeBadge = function(mode) {
            if (mode === 'live') { return 'trk-badge--green'; }
            if (mode === 'sandbox') { return 'trk-badge--amber'; }
            return 'trk-badge--grey';
        };

        // ── "Sync GoCardless fees" (§5) — import costs from the payout API.
        // The run is time-budgeted (~20s) and resumable: keep calling while
        // complete:false, accumulating the counters, then refetch the data.
        vm.syncFees = function() {
            if (vm.syncing) { return; }
            vm.syncing = true;
            vm.sync_progress = 'Syncing…';
            var acc = { payouts: 0, already: 0, archived: 0, gateway_fees: 0,
                        app_fees: 0, settled: 0, errors: [] };
            syncStep(acc);
        };
        function syncStep(acc) {
            var payload = {};
            if (vm.f.club_id) { payload.club_id = parseInt(vm.f.club_id, 10); }
            GclMonitorService.FeeSync(payload).then(function(data) {
                if (data && data.success === false) {
                    vm.syncing = false;
                    vm.sync_progress = null;
                    toastFail('Fee sync failed', data);
                    return;
                }
                acc.payouts += (parseInt(data.payouts_synced, 10) || 0);
                acc.already += (parseInt(data.payouts_already_synced, 10) || 0);
                acc.archived += (parseInt(data.payouts_archived, 10) || 0);
                acc.gateway_fees += (parseFloat(data.gateway_fees_recorded) || 0);
                acc.app_fees += (parseInt(data.app_fees_backfilled, 10) || 0);
                acc.settled += (parseInt(data.statuses_settled, 10) || 0);
                acc.errors = acc.errors.concat(data.errors || []);
                if (!data.complete) {
                    vm.sync_progress = 'Syncing… ' + acc.payouts + ' payout' + (acc.payouts === 1 ? '' : 's') + ' done';
                    syncStep(acc);
                    return;
                }
                vm.syncing = false;
                vm.sync_progress = null;
                var detail = '£' + acc.gateway_fees.toFixed(2) + ' gateway fees recorded, ' +
                             acc.app_fees + ' historical platform fee' + (acc.app_fees === 1 ? '' : 's') + ' recovered, ' +
                             acc.settled + ' stuck payment status' + (acc.settled === 1 ? '' : 'es') + ' settled.';
                if (acc.archived) {
                    detail += ' ' + acc.archived + ' payout' + (acc.archived === 1 ? '' : 's') +
                              ' are archived by GoCardless (older than ~6 months) and could not be fetched.';
                }
                ToastService.success('Synced ' + acc.payouts + ' payout' + (acc.payouts === 1 ? '' : 's'), detail);
                if (acc.errors.length) {
                    ToastService.warning('Some clubs failed to sync', acc.errors.map(function(e) {
                        return 'Club ' + e.club_id + ': ' + e.error;
                    }).join(' · '));
                }
                loadFees();
            });
        }

        // ══════════════════════════════════════════════════════════════════
        // REVENUE — app fees + tracker invoices, always per-currency
        // ══════════════════════════════════════════════════════════════════
        function initRevenue() {
            vm.from = moment().subtract(11, 'months').startOf('month').toDate();
            vm.to = new Date();
            loadRevenue();
        }
        vm.applyRange = function() { loadRevenue(); };
        function loadRevenue() {
            vm.loading = true;
            GclMonitorService.Revenue({ from: ymd(vm.from), to: ymd(vm.to) }).then(function(data) {
                vm.loading = false;
                if (data && data.success === false) { toastFail('Could not load the revenue report', data); return; }
                vm.revenue = data;
                buildRevenueSummary();
            });
        }
        // NEVER sum across currencies — one tile row / chart per currency.
        function buildRevenueSummary() {
            var pf = (vm.revenue && vm.revenue.platform_fees) || {};
            var tr = (vm.revenue && vm.revenue.tracker_revenue) || {};
            var currencies = {};
            (pf.totals || []).forEach(function(r) { currencies[r.currency] = true; });
            (tr.totals || []).forEach(function(r) { currencies[r.currency] = true; });
            vm.currencies = Object.keys(currencies).sort();
            vm.summaries = vm.currencies.map(function(c) {
                var sums = { collected: 0, pending: 0, lost: 0, payments: 0 };
                (pf.totals || []).forEach(function(r) {
                    if (r.currency !== c) { return; }
                    var state = sums.hasOwnProperty(r.fee_state) ? r.fee_state : 'lost';
                    sums[state] += vm.num(r.fees);
                    if (r.fee_state === 'collected') { sums.payments += (parseInt(r.payments, 10) || 0); }
                });
                var tracker = { revenue: 0, invoices: 0 };
                (tr.totals || []).forEach(function(r) {
                    if (r.currency !== c) { return; }
                    tracker.revenue += vm.num(r.revenue);
                    tracker.invoices += (parseInt(r.invoices, 10) || 0);
                });
                return { currency: c, fees: sums, tracker: tracker };
            });
            // Biggest currency first — it also becomes the chart/table default
            vm.summaries.sort(function(a, b) {
                return (b.fees.collected + b.tracker.revenue) - (a.fees.collected + a.tracker.revenue);
            });
            vm.chartCurrency = vm.summaries.length ? vm.summaries[0].currency : null;
            buildChart();
        }
        vm.setChartCurrency = function(c) { vm.chartCurrency = c; buildChart(); };
        // Monthly stacked bars: collected platform fees + tracker revenue,
        // sized against the biggest month so the shape reads instantly.
        function buildChart() {
            vm.chart = [];
            if (!vm.chartCurrency || !vm.revenue) { return; }
            var pf = vm.revenue.platform_fees || {};
            var tr = vm.revenue.tracker_revenue || {};
            var months = {};
            (pf.by_month || []).forEach(function(r) {
                if (r.currency !== vm.chartCurrency || r.fee_state !== 'collected') { return; }
                months[r.month] = months[r.month] || { fees: 0, tracker: 0 };
                months[r.month].fees += vm.num(r.fees);
            });
            (tr.by_month || []).forEach(function(r) {
                if (r.currency !== vm.chartCurrency) { return; }
                months[r.month] = months[r.month] || { fees: 0, tracker: 0 };
                months[r.month].tracker += vm.num(r.revenue);
            });
            var keys = Object.keys(months).sort();
            var max = 0;
            keys.forEach(function(m) { max = Math.max(max, months[m].fees + months[m].tracker); });
            vm.chart = keys.map(function(m, i) {
                return {
                    month: m,
                    label: moment(m, 'YYYY-MM').format('MMM YY'),
                    fees: months[m].fees,
                    tracker: months[m].tracker,
                    feesPct: max ? (months[m].fees / max * 100) : 0,
                    trackerPct: max ? (months[m].tracker / max * 100) : 0,
                    delay: i * 40
                };
            });
        }
        vm.byClub = function() {
            var rows = ((vm.revenue || {}).platform_fees || {}).by_club || [];
            return rows.filter(function(r) { return !vm.chartCurrency || r.currency === vm.chartCurrency; });
        };
        vm.byMethod = function() {
            var rows = ((vm.revenue || {}).platform_fees || {}).by_method || [];
            return rows.filter(function(r) { return !vm.chartCurrency || r.currency === vm.chartCurrency; });
        };
    }

// ═══════════════════════════════════════════════════════════════════
//  PlatformKeysController
//  ToAviate super-admin — API keys for external platforms calling
//  ToAviate server-to-server (airshows.toaviate, future partners).
//  One controller for both screens, dispatched on
//  $state.current.data.screen:
//     'list'    → landing table (status, scopes, usage, quick actions)
//     'detail'  → one key: audit block, edit, rotate, revoke, delete
//  Create/edit happen in PlatformKeyFormModalCtrl; the full secret is
//  shown exactly once (create + rotate) by PlatformKeySecretModalCtrl.
//  Backend contract: FRONTEND_PLATFORM_KEYS_ADMIN_GUIDE.md
// ═══════════════════════════════════════════════════════════════════

app.controller('PlatformKeysController', PlatformKeysController);

PlatformKeysController.$inject = ['PlatformKeyService', 'ToastService', 'EnvConfig',
                                  '$rootScope', '$state', '$stateParams', '$uibModal', '$timeout'];
function PlatformKeysController(PlatformKeyService, ToastService, EnvConfig,
                                $rootScope, $state, $stateParams, $uibModal, $timeout) {
    var vm = this;

    // ── Access gate — ToAviate platform staff only (backend is authoritative) ──
    vm.user     = $rootScope.globals.currentUser;
    vm.is_staff = $rootScope.isToAviateStaff();

    vm.screen   = ($state.current.data && $state.current.data.screen) || 'list';

    vm.loading  = true;
    vm.busy     = false;      // an action (rotate/revoke/…) is in flight
    vm.confirm  = null;       // pending confirmation { action, key, title, message, label, danger }

    // ── Exposed API ──
    vm.statusOf     = PlatformKeyService.statusOf;
    vm.statusLabel  = statusLabel;
    vm.scopeParts   = PlatformKeyService.parseScope;
    vm.num          = num;                 // MySQL returns numerics as strings
    vm.ago          = ago;
    vm.askRotate     = askRotate;
    vm.askRevoke     = askRevoke;
    vm.askReactivate = askReactivate;
    vm.cancelConfirm = function () { vm.confirm = null; };
    vm.runConfirm    = runConfirm;
    vm.openCreate    = openCreate;
    vm.copyText      = copyText;

    if (!vm.is_staff) {
        vm.loading = false;
        return;
    }

    if (vm.screen === 'detail') { initDetail(); }
    else                        { initList(); }


    // ═══════════════════════════════════════════════════════════════
    //  SCREEN 1 — LIST
    // ═══════════════════════════════════════════════════════════════

    function initList() {
        vm.keys          = [];
        vm.search        = '';
        vm.status_filter = 'all';        // all | active | revoked | disabled
        vm.stats         = { total: 0, active: 0, calls: 0, last_used: null };

        vm.loadKeys        = loadKeys;
        vm.setStatusFilter = function (f) { vm.status_filter = f; };
        vm.rowVisible      = rowVisible;
        vm.visibleCount    = visibleCount;

        loadKeys();
    }

    function loadKeys() {
        vm.loading = true;
        PlatformKeyService.GetAll().then(function (data) {
            vm.loading = false;

            if (!data || data.success === false || !data.keys) {
                ToastService.error('Could not load platform keys',
                    messageOf(data, 'The key list did not load. Try again.'));
                return;
            }

            vm.keys = data.keys;

            var stats = { total: data.keys.length, active: 0, calls: 0, last_used: null };
            angular.forEach(data.keys, function (k) {
                if (vm.statusOf(k) === 'active') { stats.active++; }
                stats.calls += num(k.use_count);
                if (k.last_used_at && (!stats.last_used || k.last_used_at > stats.last_used)) {
                    stats.last_used = k.last_used_at;
                }
            });
            vm.stats = stats;
        });
    }

    function rowVisible(key) {
        if (vm.status_filter !== 'all' && vm.statusOf(key) !== vm.status_filter) {
            return false;
        }
        if (!vm.search) { return true; }
        var q = vm.search.toLowerCase();
        var haystack = [key.platform_name, key.description, key.key_prefix]
            .concat(key.allowed_endpoints || []).join(' ').toLowerCase();
        return haystack.indexOf(q) > -1;
    }

    function visibleCount() {
        var n = 0;
        angular.forEach(vm.keys, function (k) { if (rowVisible(k)) { n++; } });
        return n;
    }


    // ═══════════════════════════════════════════════════════════════
    //  SCREEN 2 — DETAIL
    // ═══════════════════════════════════════════════════════════════

    function initDetail() {
        vm.key       = null;
        vm.not_found = false;

        vm.openEdit   = openEdit;
        vm.askDelete  = askDelete;
        vm.curlSnippet = curlSnippet;

        loadKey();
    }

    function loadKey() {
        vm.loading = true;
        PlatformKeyService.GetOne($stateParams.id).then(function (data) {
            vm.loading = false;

            if (!data || data.success === false || !data.key) {
                if (data && data.error === 'NOT_FOUND') {
                    vm.not_found = true;
                    return;
                }
                ToastService.error('Could not load platform key',
                    messageOf(data, 'The key did not load. Try again.'));
                vm.not_found = true;
                return;
            }

            vm.key = data.key;
        });
    }

    function openEdit() {
        openFormModal(vm.key).result.then(function (outcome) {
            if (outcome && outcome.updated) {
                vm.key = outcome.updated;
                ToastService.success('Platform key updated',
                    vm.key.platform_name + ' has been saved.');
            }
        }, function () {});
    }

    // Server-to-server integration snippet to hand to the partner.
    function curlSnippet(key) {
        return "curl 'https://v1.toaviate.com/api/v1/airshows/aircraft/g-as' \\\n" +
               "  -H 'Api-Key: " + EnvConfig.getApiKey() + "' \\\n" +
               "  -H 'Platform-Key: " + (key ? key.key_prefix : 'tak_') + "…' \\\n" +
               "  -H 'Accept: application/json'";
    }


    // ═══════════════════════════════════════════════════════════════
    //  ACTIONS (shared) — every destructive action confirms first
    // ═══════════════════════════════════════════════════════════════

    function askRotate(key) {
        vm.confirm = {
            action: 'rotate', key: key, danger: true,
            title: 'Rotate this key?',
            message: 'Rotating issues a new key and instantly breaks the ' +
                     'platform’s current one. ' + key.platform_name +
                     ' will lose access until it installs the new key.',
            label: 'Rotate key'
        };
    }

    function askRevoke(key) {
        vm.confirm = {
            action: 'revoke', key: key, danger: true,
            title: 'Revoke this key?',
            message: key.platform_name + ' will be blocked immediately. The key ' +
                     'and its usage history are kept, and it can be re-activated later.',
            label: 'Revoke now'
        };
    }

    function askReactivate(key) {
        vm.confirm = {
            action: 'reactivate', key: key, danger: false,
            title: 'Re-activate this key?',
            message: key.platform_name + '’s existing secret will start ' +
                     'working again immediately.',
            label: 'Re-activate'
        };
    }

    function askDelete(key) {
        vm.confirm = {
            action: 'delete', key: key, danger: true,
            title: 'Delete this key permanently?',
            message: 'Revoked keys keep their audit history; deleting is permanent ' +
                     'and removes the usage record for ' + key.platform_name +
                     '. Prefer revoking unless the row was created in error.',
            label: 'Delete permanently'
        };
    }

    function runConfirm() {
        if (!vm.confirm || vm.busy) { return; }
        var action = vm.confirm.action;
        var key    = vm.confirm.key;

        vm.busy = true;

        if (action === 'rotate')          { doRotate(key); }
        else if (action === 'revoke')     { doRevoke(key); }
        else if (action === 'reactivate') { doReactivate(key); }
        else if (action === 'delete')     { doDelete(key); }
    }

    function doRotate(key) {
        PlatformKeyService.Regenerate(key.id).then(function (data) {
            finishAction();

            if (!data || data.success === false || !data.key) {
                ToastService.error('Rotate failed',
                    messageOf(data, 'The key was not rotated. Try again.'));
                return;
            }

            openSecretModal({
                mode: 'rotated',
                platform_name: key.platform_name,
                key: data.key,
                key_prefix: data.key_prefix
            });
            refresh();
        });
    }

    function doRevoke(key) {
        PlatformKeyService.Revoke(key.id).then(function (data) {
            finishAction();

            if (!data || data.success === false) {
                ToastService.error('Revoke failed',
                    messageOf(data, 'The key was not revoked. Try again.'));
                return;
            }

            ToastService.success('Key revoked',
                key.platform_name + ' is blocked with immediate effect.');
            applyUpdated(data.key, key);
        });
    }

    function doReactivate(key) {
        PlatformKeyService.Update(key.id, { active: 1 }).then(function (data) {
            finishAction();

            if (!data || data.success === false) {
                ToastService.error('Re-activate failed',
                    messageOf(data, 'The key was not re-activated. Try again.'));
                return;
            }

            ToastService.success('Key re-activated',
                key.platform_name + '’s key is live again.');
            applyUpdated(data.key, key);
        });
    }

    function doDelete(key) {
        PlatformKeyService.Delete(key.id).then(function (data) {
            finishAction();

            if (!data || data.success === false) {
                ToastService.error('Delete failed',
                    messageOf(data, 'The key was not deleted. Try again.'));
                return;
            }

            ToastService.success('Key deleted',
                key.platform_name + ' has been permanently removed.');

            if (vm.screen === 'detail') {
                $state.go('dashboard.super_admin.platform_keys');
            } else {
                refresh();
            }
        });
    }

    function finishAction() {
        vm.busy    = false;
        vm.confirm = null;
    }

    // After revoke / re-activate the backend returns the updated key —
    // patch it in place so the row/status flips without a full reload.
    function applyUpdated(updatedKey, fallbackKey) {
        if (vm.screen === 'detail') {
            if (updatedKey) { vm.key = updatedKey; }
            else            { loadKey(); }
            return;
        }
        if (updatedKey && vm.keys) {
            for (var i = 0; i < vm.keys.length; i++) {
                if (vm.keys[i].id == updatedKey.id) {
                    vm.keys[i] = updatedKey;
                    break;
                }
            }
            recount();
        } else {
            refresh();
        }
    }

    function recount() {
        var stats = { total: vm.keys.length, active: 0, calls: 0, last_used: null };
        angular.forEach(vm.keys, function (k) {
            if (vm.statusOf(k) === 'active') { stats.active++; }
            stats.calls += num(k.use_count);
            if (k.last_used_at && (!stats.last_used || k.last_used_at > stats.last_used)) {
                stats.last_used = k.last_used_at;
            }
        });
        vm.stats = stats;
    }

    function refresh() {
        if (vm.screen === 'detail') { loadKey(); }
        else                        { vm.loadKeys(); }
    }


    // ═══════════════════════════════════════════════════════════════
    //  MODALS
    // ═══════════════════════════════════════════════════════════════

    function openCreate() {
        openFormModal(null).result.then(function (outcome) {
            if (outcome && outcome.created) {
                openSecretModal({
                    mode: 'created',
                    platform_name: outcome.platform_name,
                    key: outcome.created.key,
                    key_prefix: outcome.created.key_prefix
                });
                refresh();
            }
        }, function () {});
    }

    function openFormModal(existing) {
        return $uibModal.open({
            templateUrl: 'views/modals/platform_key_form.html',
            controller: 'PlatformKeyFormModalCtrl',
            controllerAs: 'vm',
            backdrop: 'static',
            resolve: {
                existing: function () { return existing ? angular.copy(existing) : null; }
            }
        });
    }

    // Show-once secret. backdrop 'static' + no Esc so a stray click can't
    // destroy the only chance to copy the key.
    function openSecretModal(payload) {
        $uibModal.open({
            templateUrl: 'views/modals/platform_key_secret.html',
            controller: 'PlatformKeySecretModalCtrl',
            controllerAs: 'vm',
            backdrop: 'static',
            keyboard: false,
            resolve: {
                payload: function () { return payload; }
            }
        });
    }


    // ═══════════════════════════════════════════════════════════════
    //  HELPERS
    // ═══════════════════════════════════════════════════════════════

    function statusLabel(key) {
        var s = vm.statusOf(key);
        if (s === 'active')  { return 'Active'; }
        if (s === 'revoked') { return 'Revoked'; }
        return 'Disabled';
    }

    function num(v) {
        var n = parseInt(v, 10);
        return isNaN(n) ? 0 : n;
    }

    // "3 minutes ago" — the at-a-glance signal that an integration is alive.
    function ago(ts) {
        if (!ts) { return 'Never'; }
        var m = moment(ts);
        return m.isValid() ? m.fromNow() : ts;
    }

    function copyText(text, what) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text);
        } else {
            var ta = document.createElement('textarea');
            ta.value = text;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            document.body.removeChild(ta);
        }
        ToastService.success('Copied', (what || 'Text') + ' copied to the clipboard.');
    }

    function messageOf(data, fallback) {
        if (data && typeof data.message === 'string' && data.message) { return data.message; }
        return fallback;
    }
}


// ═══════════════════════════════════════════════════════════════════
//  PlatformKeyFormModalCtrl — create / edit a platform key.
//  Scopes are edited as method-dropdown + path-text rows and serialised
//  to "METHOD path" strings; IPs as removable tags (empty list = any IP).
// ═══════════════════════════════════════════════════════════════════

app.controller('PlatformKeyFormModalCtrl', PlatformKeyFormModalCtrl);

PlatformKeyFormModalCtrl.$inject = ['PlatformKeyService', 'ToastService',
                                    '$uibModalInstance', 'existing'];
function PlatformKeyFormModalCtrl(PlatformKeyService, ToastService,
                                  $uibModalInstance, existing) {
    var vm = this;

    vm.mode    = existing ? 'edit' : 'create';
    vm.methods = PlatformKeyService.scope_methods;
    vm.saving  = false;
    vm.errors  = {};

    vm.form = {
        platform_name: existing ? existing.platform_name : '',
        description:   existing ? (existing.description || '') : '',
        active:        existing ? parseInt(existing.active, 10) === 1 : true
    };

    // Scope rows: [{ method, path }]
    vm.scopes = [];
    if (existing && existing.allowed_endpoints && existing.allowed_endpoints.length) {
        angular.forEach(existing.allowed_endpoints, function (s) {
            vm.scopes.push(PlatformKeyService.parseScope(s));
        });
    } else {
        vm.scopes.push({ method: 'GET', path: '' });
    }

    // IP allow-list tags (empty = any IP)
    vm.ips    = (existing && existing.allowed_ips) ? existing.allowed_ips.slice() : [];
    vm.ip_new = '';

    vm.addScope    = function () { vm.scopes.push({ method: 'GET', path: '' }); };
    vm.removeScope = function (i) { vm.scopes.splice(i, 1); };
    vm.addIp       = addIp;
    vm.removeIp    = function (i) { vm.ips.splice(i, 1); };
    vm.save        = save;
    vm.cancel      = function () { $uibModalInstance.dismiss('cancel'); };

    function addIp() {
        var ip = String(vm.ip_new || '').trim();
        if (!ip) { return; }
        if (vm.ips.indexOf(ip) === -1) { vm.ips.push(ip); }
        vm.ip_new = '';
    }

    function save() {
        if (vm.saving) { return; }

        // Uncommitted text in the IP box counts — nobody presses Add twice.
        addIp();

        vm.errors = {};

        var scopes = [];
        angular.forEach(vm.scopes, function (s) {
            var path = String(s.path || '').trim().toLowerCase();
            if (path) { scopes.push(s.method + ' ' + path); }
        });

        if (!String(vm.form.platform_name || '').trim()) { vm.errors.platform_name = true; }
        if (!scopes.length)                              { vm.errors.scopes = true; }
        if (vm.errors.platform_name || vm.errors.scopes) {
            ToastService.warning('Missing details',
                'A platform name and at least one endpoint scope are required.');
            return;
        }

        var payload = {
            platform_name:     String(vm.form.platform_name).trim(),
            description:       String(vm.form.description || '').trim(),
            allowed_endpoints: scopes,
            allowed_ips:       vm.ips.length ? vm.ips : null
        };

        vm.saving = true;

        if (vm.mode === 'create') {
            PlatformKeyService.Create(payload).then(function (data) {
                vm.saving = false;

                if (!data || data.success === false || !data.key) {
                    ToastService.error('Could not create key',
                        failMessage(data, 'The key was not created. Try again.'));
                    return;
                }

                $uibModalInstance.close({
                    created: data,
                    platform_name: payload.platform_name
                });
            });
        } else {
            payload.active = vm.form.active ? 1 : 0;

            PlatformKeyService.Update(existing.id, payload).then(function (data) {
                vm.saving = false;

                if (!data || data.success === false || !data.key) {
                    ToastService.error('Could not save key',
                        failMessage(data, 'The changes were not saved. Try again.'));
                    return;
                }

                $uibModalInstance.close({ updated: data.key });
            });
        }
    }

    // VALIDATION errors arrive with success:false and a human-readable message.
    function failMessage(data, fallback) {
        if (data && typeof data.message === 'string' && data.message) { return data.message; }
        return fallback;
    }
}


// ═══════════════════════════════════════════════════════════════════
//  PlatformKeySecretModalCtrl — the show-once secret after create or
//  rotate. The key exists only inside this modal; it is never stored.
// ═══════════════════════════════════════════════════════════════════

app.controller('PlatformKeySecretModalCtrl', PlatformKeySecretModalCtrl);

PlatformKeySecretModalCtrl.$inject = ['ToastService', 'EnvConfig', '$uibModalInstance', 'payload'];
function PlatformKeySecretModalCtrl(ToastService, EnvConfig, $uibModalInstance, payload) {
    var vm = this;

    vm.mode          = payload.mode;                 // 'created' | 'rotated'
    vm.platform_name = payload.platform_name;
    vm.key           = payload.key;
    vm.key_prefix    = payload.key_prefix;
    vm.copied        = false;

    vm.snippet = "curl 'https://v1.toaviate.com/api/v1/airshows/aircraft/g-as' \\\n" +
                 "  -H 'Api-Key: " + EnvConfig.getApiKey() + "' \\\n" +
                 "  -H 'Platform-Key: " + payload.key + "' \\\n" +
                 "  -H 'Accept: application/json'";

    vm.copyKey     = function () { copy(vm.key, 'The key'); vm.copied = true; };
    vm.copySnippet = function () { copy(vm.snippet, 'The integration snippet'); vm.copied = true; };
    vm.done        = function () { $uibModalInstance.close(); };

    function copy(text, what) {
        if (navigator.clipboard && navigator.clipboard.writeText) {
            navigator.clipboard.writeText(text);
        } else {
            var ta = document.createElement('textarea');
            ta.value = text;
            document.body.appendChild(ta);
            ta.select();
            document.execCommand('copy');
            document.body.removeChild(ta);
        }
        ToastService.success('Copied', what + ' is on the clipboard.');
    }
}

// ─────────────────────────────────────────────────────
// RecordsToFileController
// Club admin "Records to file" page (Members hub tab). Every completed
// instructional flight of the selected admin club that still has no student
// training record, plus the records an admin entered on an instructor's
// behalf that the instructor has not confirmed yet.
//
// "File record" opens the normal instructor debrief form for the flight with
// from=records_to_file, so a save comes straight back here (and the page
// reloads — the controller re-initialises on entry). The view, instructor
// and date filters survive that round trip via sessionStorage.
//
// Backend contract: BACKEND_ADMIN_STUDENT_RECORDS_GUIDE.md
//   GET training_records/to_file/{club_id}      (RecordsToFileService.Queue)
//   GET training_records/unconfirmed/{club_id}  (RecordsToFileService.Unconfirmed)
// ─────────────────────────────────────────────────────
app.controller('RecordsToFileController', RecordsToFileController);

    RecordsToFileController.$inject = ['RecordsToFileService', 'ToastService', 'TimeDisplayService', '$rootScope', '$scope', '$state', '$stateParams', '$uibModal'];
    function RecordsToFileController(RecordsToFileService, ToastService, TimeDisplayService, $rootScope, $scope, $state, $stateParams, $uibModal) {
        var vm = this;

        var STORE_KEY = 'toaviate_records_to_file_filters';
        var PER_PAGE = 50;

        var cu = $rootScope.globals.currentUser;
        vm.club_id = (cu.current_club_admin && cu.current_club_admin.id) || null;

        // Training-record times: brakes off → on, the club's rounding.
        vm.td = TimeDisplayService.context(vm.club_id, { window: 'block' });

        vm.tab = ($stateParams.tab === 'awaiting') ? 'awaiting' : 'to_file';

        // ── To-file list state ──
        vm.view = 'ready';                 // 'ready' (has a student) | 'needs_student' | 'all'
        // record_kind: '' all | 'none' no record at all | 'import_note' only the TPC import note so far
        vm.filters = { instructor: '', date_from: null, date_to: null, record_kind: '' };
        vm.flights = [];
        vm.total = 0;
        vm.page = 1;
        vm.loading = false;
        vm.paging = false;       // swapping to another page (the list dims, the pager locks)
        vm.loaded = false;
        vm.forbidden = false;
        vm.summary = null;
        vm.instructor_choices = [{ value: '', label: 'All instructors' }];

        // ── Awaiting-confirmation list state ──
        vm.awaiting = [];
        vm.awaiting_loading = false;
        vm.awaiting_loaded = false;
        vm.awaiting_filter = '';           // instructor id (client-side filter)
        vm.awaiting_instructors = [];

        var seq = 0;                       // drops stale responses when filters change quickly

        // ── Filter persistence (per viewer, per tab session) ──
        function ymd(d) {
            if (!d || !(d instanceof Date) || isNaN(d.getTime())) { return null; }
            var m = d.getMonth() + 1, day = d.getDate();
            return d.getFullYear() + '-' + (m < 10 ? '0' : '') + m + '-' + (day < 10 ? '0' : '') + day;
        }
        function fromYmd(s) {
            if (!s || !/^\d{4}-\d{2}-\d{2}$/.test(s)) { return null; }
            var p = s.split('-');
            return new Date(Number(p[0]), Number(p[1]) - 1, Number(p[2]));
        }
        function saveFilters() {
            try {
                sessionStorage.setItem(STORE_KEY, JSON.stringify({
                    club_id: vm.club_id,
                    view: vm.view,
                    instructor: vm.filters.instructor || '',
                    record_kind: vm.filters.record_kind || '',
                    page: vm.page || 1,
                    date_from: ymd(vm.filters.date_from),
                    date_to: ymd(vm.filters.date_to)
                }));
            } catch (e) {}
        }
        function restoreFilters() {
            try {
                var raw = sessionStorage.getItem(STORE_KEY);
                if (!raw) { return; }
                var s = JSON.parse(raw);
                // Filters belong to one club — a club switch starts clean.
                if (!s || String(s.club_id) !== String(vm.club_id)) { return; }
                if (s.view === 'ready' || s.view === 'needs_student' || s.view === 'all') { vm.view = s.view; }
                vm.filters.instructor = s.instructor || '';
                vm.filters.record_kind = (s.record_kind === 'none' || s.record_kind === 'import_note') ? s.record_kind : '';
                vm.page = Math.max(1, parseInt(s.page, 10) || 1);
                vm.filters.date_from = fromYmd(s.date_from);
                vm.filters.date_to = fromYmd(s.date_to);
            } catch (e) {}
        }

        // ── Display helpers ──
        vm.personName = function(p) {
            if (!p) { return ''; }
            return ((p.first_name || '') + ' ' + (p.last_name || '')).trim();
        };
        vm.sheetName = function(f) {
            return (f && f.suggested_student) ? vm.personName(f.suggested_student) : '';
        };
        vm.kindLabel = function(kind) {
            if (kind === 'dual') { return 'Dual'; }
            if (kind === 'supervised_solo') { return 'Supervised solo'; }
            return 'Instructional';
        };
        vm.readyCount = function() {
            if (!vm.summary) { return 0; }
            return Math.max(0, (vm.summary.open || 0) - (vm.summary.no_student || 0));
        };
        vm.hasFilters = function() {
            return !!(vm.filters.instructor || vm.filters.record_kind || vm.filters.date_from || vm.filters.date_to);
        };
        // "Showing 51–100" for the toolbar (the pager under the list says the same)
        vm.rangeFrom = function() { return vm.total ? (vm.page - 1) * PER_PAGE + 1 : 0; };
        vm.rangeTo = function() { return Math.min(vm.total, (vm.page - 1) * PER_PAGE + vm.flights.length); };
        vm.perPage = PER_PAGE;

        // Instructor picker options come from the whole-club summary.
        function buildInstructorChoices() {
            var s = vm.summary || {};
            var out = [{ value: '', label: 'All instructors' }];
            (s.by_instructor || []).forEach(function(row) {
                var ins = row.instructor || {};
                var name = vm.personName(ins) || ('Instructor #' + ins.id);
                // "Ready to file" counts only flights that already have a student
                var n = (vm.view === 'ready' && row.ready !== undefined) ? row.ready : row.count;
                out.push({ value: String(ins.id), label: name + ' (' + (n || 0) + ')' });
            });
            if (s.no_instructor > 0) {
                out.push({ value: 'none', label: 'No instructor named (' + s.no_instructor + ')' });
            }
            // A remembered instructor who no longer has open flights still shows,
            // so the select never silently disagrees with the list.
            if (vm.filters.instructor && !out.some(function(o) { return o.value === vm.filters.instructor; })) {
                out.push({ value: vm.filters.instructor, label: vm.filters.instructor === 'none' ? 'No instructor named (0)' : 'Selected instructor (0)' });
            }
            vm.instructor_choices = out;
        }

        function queryParams(page) {
            var p = { page: page, per_page: PER_PAGE };
            if (vm.view === 'ready') { p.has_student = 1; }
            if (vm.view === 'needs_student') { p.no_student = 1; }
            if (vm.filters.instructor === 'none') {
                p.no_instructor = 1;
            } else if (vm.filters.instructor) {
                p.instructor_id = vm.filters.instructor;
            }
            if (vm.filters.record_kind) { p.record_kind = vm.filters.record_kind; }
            p.date_from = ymd(vm.filters.date_from);
            p.date_to = ymd(vm.filters.date_to);
            return p;
        }

        function handleForbidden(data) {
            var forbidden = data && (data.error === 'FORBIDDEN' || data.status === 403);
            if (forbidden && !vm.forbidden) {
                vm.forbidden = true;
                ToastService.error('No Access', 'Only club managers and super-admins of this club can file records on an instructor\'s behalf.');
            }
            return forbidden;
        }

        // ── To-file list ──
        // load() = page 1 (a filter changed); goPage(n) keeps the filters. The
        // backend clamps a page past the end to the last one.
        vm.load = function(page) {
            if (!vm.club_id) { return; }
            var mine = ++seq;
            var first = !vm.loaded;
            // the very first load resumes the remembered page (back from filing a record)
            vm.page = (page && page > 0) ? page : (first ? (vm.page || 1) : 1);
            vm.loading = !vm.loaded;
            vm.paging = vm.loaded;
            saveFilters();
            RecordsToFileService.Queue(vm.club_id, queryParams(vm.page)).then(function(data) {
                if (mine !== seq) { return; }
                vm.loading = false;
                vm.paging = false;
                vm.loaded = true;
                if (data && data.success) {
                    vm.flights = data.flights || [];
                    vm.total = data.total || 0;
                    vm.page = data.page || vm.page;
                    saveFilters();
                    vm.summary = data.summary || vm.summary;
                    buildInstructorChoices();
                } else {
                    vm.flights = [];
                    vm.total = 0;
                    if (!handleForbidden(data)) {
                        ToastService.error('Load Failed', (data && data.message) || 'Could not load the flights that need a record.');
                    }
                }
            });
        };

        vm.goPage = function(page) { vm.load(page); };

        vm.setView = function(view) {
            if (vm.view === view && vm.tab === 'to_file') { return; }
            vm.view = view;
            vm.setTab('to_file');
            vm.load();
        };

        vm.onInstructorChange = function() { vm.load(); };
        vm.applyDates = function() {
            if (vm.filters.date_from && vm.filters.date_to && vm.filters.date_from > vm.filters.date_to) {
                ToastService.warning('Check The Dates', 'The "from" date is after the "to" date.');
                return;
            }
            vm.load();
        };
        vm.clearFilters = function() {
            vm.filters.instructor = '';
            vm.filters.record_kind = '';
            vm.filters.date_from = null;
            vm.filters.date_to = null;
            vm.load();
        };

        // ── Actions on a flight ──
        // The normal instructor debrief form. booking_id 0 for a log-sheet-only
        // flight (the form looks the booking up from the sheet either way);
        // plane_log_sheet_id > 0 makes it load via for_debrief_pls.
        vm.fileRecord = function(f) {
            if (!f || f.needs_book_in == 1 || !f.student) { return; }
            $state.go('dashboard.manage_user.debriefing', {
                booking_id: (f.booking_id && Number(f.booking_id) > 0) ? Number(f.booking_id) : 0,
                plane_log_sheet_id: f.plane_log_sheet_id,
                split_next_id: null,
                split_booking_id: null,
                from: 'records_to_file'
            });
        };

        // "Resolve student…" — the same inline modal the instructor debrief list
        // uses (assign an existing member / create a temporary one for this
        // flight, optionally the other flights carrying the same sheet name).
        vm.resolveStudent = function(f) {
            var modal = $uibModal.open({
                templateUrl: 'views/modals/missing_student_resolve.html',
                controller: 'MissingStudentResolveModalController',
                controllerAs: 'vm',
                size: 'md',
                backdrop: 'static',
                windowClass: 'msq-modal-window',
                resolve: {
                    log: function() { return f; },
                    club_id: function() { return vm.club_id; }
                }
            });
            modal.result.then(function(res) {
                if (res && res.fixed) { vm.load(vm.page); }   // stay on this page
            }, function() {});
        };

        // ── Awaiting instructor confirmation ──
        function buildAwaitingInstructors() {
            var seen = {};
            var out = [];
            vm.awaiting.forEach(function(r) {
                var id = String(r.instructor_id || '');
                if (!id || seen[id]) { return; }
                seen[id] = true;
                out.push({ value: id, label: ((r.instructor_first_name || '') + ' ' + (r.instructor_last_name || '')).trim() || ('Instructor #' + id) });
            });
            out.sort(function(a, b) { return a.label.localeCompare(b.label); });
            vm.awaiting_instructors = [{ value: '', label: 'All instructors' }].concat(out);
            if (vm.awaiting_filter && !seen[vm.awaiting_filter]) { vm.awaiting_filter = ''; }
        }

        vm.loadAwaiting = function() {
            if (!vm.club_id) { return; }
            vm.awaiting_loading = true;
            RecordsToFileService.Unconfirmed(vm.club_id, {}).then(function(data) {
                vm.awaiting_loading = false;
                vm.awaiting_loaded = true;
                if (data && data.success) {
                    vm.awaiting = data.records || [];
                    if (vm.summary) { vm.summary.awaiting_confirmation = data.count || vm.awaiting.length; }
                    buildAwaitingInstructors();
                } else {
                    vm.awaiting = [];
                    if (!handleForbidden(data)) {
                        ToastService.error('Load Failed', (data && data.message) || 'Could not load the records awaiting confirmation.');
                    }
                }
            });
        };

        vm.awaitingFiltered = function() {
            if (!vm.awaiting_filter) { return vm.awaiting; }
            return vm.awaiting.filter(function(r) { return String(r.instructor_id) === vm.awaiting_filter; });
        };

        vm.setTab = function(tab) {
            if (tab !== 'to_file' && tab !== 'awaiting') { return; }
            if (vm.tab !== tab) {
                vm.tab = tab;
                // Keep the tab in the URL (refresh / back) without re-entering the state.
                $state.go('dashboard.manage_club.records_to_file', { tab: tab === 'awaiting' ? 'awaiting' : null }, { notify: false, location: 'replace' });
            }
            if (tab === 'awaiting' && !vm.awaiting_loaded && !vm.awaiting_loading) { vm.loadAwaiting(); }
        };

        // ── Start ──
        function start() {
            vm.td.setClub(vm.club_id);
            restoreFilters();
            vm.load();
            if (vm.tab === 'awaiting') { vm.loadAwaiting(); }
        }

        if (vm.club_id) {
            start();
        } else {
            // First visit straight to this URL: the Manage Club parent picks the
            // admin club asynchronously (DashboardController.GetAdminClubs).
            var stopWatch = $scope.$watch(function() {
                var c = $rootScope.globals.currentUser && $rootScope.globals.currentUser.current_club_admin;
                return c && c.id;
            }, function(id) {
                if (!id) { return; }
                stopWatch();
                vm.club_id = id;
                start();
            });
        }
    }

